// who the famous people were, in a few lines: the first is their life and death, the rest are curious facts (keys are the Bulgarian names)
export const BIO_DE: Record<string, string[]> = {
  "Имхотеп": ["Ein ägyptischer Weiser und Berater des Pharaos Djoser. Er baute die erste Pyramide der Welt, die Stufenpyramide von Sakkara. Er war nicht nur Baumeister, sondern auch Heiler; wann und wie er starb, weiß niemand.", "Er ist der erste Baumeister der Geschichte, dessen Namen wir kennen.", "Etwa 2000 Jahre nach seinem Tod beteten die Ägypter zu ihm als Gott der Heilkunst."],
  "Хамурапи": ["Ein König von Babylon, der fast ganz Mesopotamien vereinte. Er ließ 282 Gesetze in eine hohe schwarze Steinsäule meißeln, damit jeder wusste, was gerecht ist. Er starb alt und krank nach etwa 42 Jahren auf dem Thron.", "Die Säule mit seinen Gesetzen wurde 1901 gefunden und steht heute im Louvre in Paris.", "Von ihr stammt die Regel „Auge um Auge, Zahn um Zahn“."],
  "Моисей": ["Laut der Bibel führte er die Hebräer aus der Sklaverei in Ägypten und 40 Jahre lang durch die Wüste. Auf dem Berg Sinai empfing er die Zehn Gebote. Er starb mit 120 Jahren auf dem Berg Nebo, von wo er das Gelobte Land sah, ohne es zu betreten.", "Als Baby legte ihn seine Mutter in einem Körbchen auf den Nil, und die Tochter des Pharaos fand ihn.", "Michelangelos Statue von ihm hat Hörner, weil das Wort für „Strahlen“ falsch übersetzt wurde."],
  "Нефертити": ["Eine ägyptische Königin, Gemahlin des Pharaos Echnaton. Gemeinsam ersetzten sie die vielen alten Götter durch einen einzigen, die Sonnenscheibe Aton. Wann und wie sie starb, weiß niemand, und ihr Grab wurde nie gefunden.", "Ihr Name bedeutet „Die Schöne ist gekommen“.", "Ihre berühmte bemalte Büste fanden deutsche Archäologen 1912; heute steht sie in Berlin."],
  "Тутанкамон": ["Er wurde mit etwa 9 Jahren Pharao und herrschte nur rund zehn Jahre über Ägypten. Er starb jung, mit etwa 18 oder 19, wohl an einer Krankheit nach einem Beinbruch. Weltberühmt wurde er, als Howard Carter 1922 sein fast unberührtes Grab fand.", "Seine goldene Maske wiegt etwa 10 Kilogramm.", "In seinem Grab lagen über 130 Gehstöcke: Er hatte einen kranken Fuß und brauchte sie."],
  "Рамзес II": ["Der mächtigste Pharao Ägyptens, der 66 Jahre lang herrschte. Er baute riesige Tempel, darunter Abu Simbel, und kämpfte bei Kadesch gegen die Hethiter. Er starb mit etwa 90 Jahren und überlebte viele seiner Kinder.", "Sein Friedensvertrag mit den Hethitern ist der älteste bekannte der Welt; eine Kopie hängt bei den Vereinten Nationen.", "Er hatte über 100 Kinder."],
  "Цар Давид": ["Laut der Bibel ein Hirtenjunge, der den Riesen Goliat mit einem einzigen Stein aus der Schleuder besiegte. Später wurde er König von Israel und machte Jerusalem zu seiner Hauptstadt. Er starb mit 70 und hinterließ den Thron seinem Sohn Salomo.", "Der Überlieferung nach schrieb er viele der Psalmen.", "Michelangelos marmorner „David“ ist über 5 Meter hoch."],
  "Цар Соломон": ["Sohn Davids und König von Israel, berühmt für seine Weisheit und seinen Reichtum. Er baute den ersten Tempel in Jerusalem. Er starb nach etwa 40 Jahren auf dem Thron, und nach ihm zerfiel das Reich in zwei.", "Im berühmten „salomonischen Urteil“ stritten zwei Frauen um ein Baby; er bot an, es zu teilen, und erkannte die wahre Mutter daran, dass sie verzichtete, um es zu retten.", "Die Königin von Saba kam, um seine Weisheit zu prüfen."],
  "Солон": ["Ein Gesetzgeber Athens und einer der Sieben Weisen. Er erließ den Armen ihre Schulden und verbot, Menschen wegen Schulden zu versklaven. Er legte den Grundstein der athenischen Demokratie und starb mit etwa 80 Jahren.", "Nachdem er seine Gesetze gegeben hatte, reiste er 10 Jahre lang, damit niemand ihn zwingen konnte, sie zu ändern.", "Dem reichen König Krösus sagte er: „Preise niemanden glücklich, bevor er gestorben ist.“"],
  "Сафо": ["Eine Dichterin von der Insel Lesbos, die ihre Verse zur Leier sang. Sie schrieb über Liebe, Freundschaft und Schönheit. Wie sie starb, ist unbekannt; die Sage, sie sei aus Liebe von einem Felsen gesprungen, ist wohl erfunden.", "Platon nannte sie „die zehnte Muse“.", "Von ihren neun Büchern ist nur ein ganzes Gedicht erhalten, der Rest sind Papyrusfetzen."],
  "Езоп": ["Ein Fabelerzähler, der der Sage nach Sklave auf der Insel Samos war und später freigelassen wurde. Die Tiere seiner Fabeln, der Fuchs, die Schildkröte, der Hase, lehren die Menschen Klugheit. Der Sage nach wurde er in Delphi getötet, von einem Felsen gestürzt.", "Die Fabel vom Fuchs, der die Trauben nicht erreicht und sie deshalb sauer nennt, stammt von ihm.", "„Der Hase und die Schildkröte“ ist von ihm."],
  "Питагор": ["Geboren auf der Insel Samos, gründete er eine Schule in Kroton in Süditalien. Seine Schüler glaubten, die Welt bestehe aus Zahlen. Er starb mit etwa 75; der Sage nach wurde er getötet, weil er nicht durch ein Bohnenfeld fliehen wollte.", "Sein Satz a² + b² = c² war den Babyloniern schon früher bekannt.", "Er fand als Erster heraus, dass schöne Töne einfache Zahlenverhältnisse sind."],
  "Буда": ["Prinz Siddhartha Gautama, geboren in Lumbini im heutigen Nepal. Mit 29 verließ er seinen Palast, nachdem er Alter, Krankheit und Tod gesehen hatte. Unter dem Bodhi-Baum erlangte er die Erleuchtung und lehrte 45 Jahre lang, wie man sich vom Leiden befreit. Er starb mit 80 in Kushinagar.", "„Buddha“ bedeutet „der Erwachte“.", "Der dicke, lachende „Buddha“ der Figuren ist jemand anderes: der chinesische Mönch Budai."],
  "Конфуций": ["Ein Lehrer aus dem Staat Lu in China. Er lehrte Achtung vor den Eltern, lebenslanges Lernen und ehrliches Regieren. Er starb mit 72, und seine Schüler schrieben seine Gedanken in den „Gesprächen“ auf.", "Von ihm stammt: „Was du nicht willst, das man dir tu, das füg auch keinem andern zu.“", "Sein Stammbaum ist über 80 Generationen lang belegt, der längste der Welt."],
  "Есхил": ["Ein Athener, „Vater der Tragödie“ genannt. Er kämpfte bei Marathon gegen die Perser und schrieb später etwa 90 Stücke, von denen 7 erhalten sind. Er starb mit 69 auf Sizilien.", "Der Sage nach ließ ein Adler eine Schildkröte auf seinen kahlen Kopf fallen, weil er ihn für einen Stein hielt.", "Auf seinem Grab steht nur, dass er bei Marathon gekämpft hat; seine Stücke werden nicht erwähnt."],
  "Софокъл": ["Ein athenischer Dramatiker, Verfasser von „König Ödipus“ und „Antigone“. Er schrieb 123 Stücke, 7 sind erhalten, und gewann etwa 24 Mal den ersten Preis. Er starb mit 91 und schrieb bis zuletzt.", "Er brachte als Erster einen dritten Schauspieler auf die Bühne.", "Als seine Söhne ihn für unzurechnungsfähig erklären lassen wollten, las er vor Gericht aus seinem neuen Stück und gewann."],
  "Перикъл": ["Der führende Mann Athens in seinem Goldenen Zeitalter. Er stärkte die Demokratie und baute den Parthenon auf der Akropolis. Er starb mit 66 an der Pest, die Athen im Krieg gegen Sparta heimsuchte.", "Er wird immer mit Helm gezeigt, angeblich um seinen ungewöhnlich langen Kopf zu verbergen.", "Seine Rede für die Gefallenen des Krieges gilt bis heute als eine der größten Reden über die Demokratie."],
  "Херодот": ["Geboren in Halikarnassos, dem heutigen Bodrum in der Türkei. Er reiste nach Ägypten, Babylon und ans Schwarze Meer und schrieb alles Gesehene in seinen „Historien“ auf, der Geschichte der Kriege zwischen Griechen und Persern. Er starb mit etwa 59, wohl in Süditalien.", "Cicero nannte ihn „Vater der Geschichtsschreibung“.", "Manche nennen ihn auch „Vater der Lügen“: Er schrieb zum Beispiel von Ameisen in Indien, groß wie Füchse, die nach Gold graben."],
  "Сократ": ["Ein Athener, Sohn eines Steinmetzen, der nie eine Zeile schrieb. Er ging über den Markt und stellte Fragen, bis die Menschen die Wahrheit selbst fanden. Er wurde zum Tode verurteilt, weil er „die Jugend verderbe“, und trank mit 71 einen Becher Schierling.", "Von ihm stammt: „Ich weiß, dass ich nichts weiß.“", "Er ging barfuß und war für sein unschönes Gesicht bekannt, doch die jungen Athener liebten ihn."],
  "Хипократ": ["Ein Arzt von der Insel Kos, „Vater der Medizin“ genannt. Er lehrte als Erster, dass Krankheiten natürliche Ursachen haben und keine Strafe der Götter sind. Er starb hochbetagt in Larissa; der Sage nach wurde er über 90.", "Ärzte leisten bis heute den „hippokratischen Eid“.", "Er beschrieb Krankheiten so genau, dass manche noch seinen Namen tragen."],
  "Демокрит": ["Geboren in Abdera in Thrakien, nicht weit von der heutigen bulgarischen Grenze. Er sagte als Erster, dass alles aus winzigen, unteilbaren Teilchen besteht: Atomen. Er starb mit etwa 90 und blieb bis zuletzt heiter.", "„Atom“ heißt auf Griechisch „unteilbar“.", "Man nennt ihn den „lachenden Philosophen“, weil er über die menschliche Torheit spottete."],
  "Платон": ["Ein Athener, Schüler des Sokrates. Er gründete die Akademie, eine Schule, die etwa 900 Jahre bestand. Er schrieb Dialoge, in denen Sokrates mit Menschen spricht, und starb mit etwa 80 in Athen.", "„Platon“ ist ein Spitzname und heißt „der Breite“, wohl wegen seiner Ringerschultern.", "Er erzählte als Erster von der versunkenen Insel Atlantis."],
  "Аристотел": ["Geboren in Stagira, Schüler Platons und Lehrer Alexanders des Großen. Er schrieb über fast alles: Logik, Physik, Tiere, Dichtung und den Staat. Er starb mit 62 in Chalkis, nachdem er Athen verlassen hatte.", "Er ordnete als Erster die Tiere in Gruppen und beschrieb über 500 Arten.", "Er lehrte im Umhergehen, deshalb heißt seine Schule die „peripatetische“, also die „umherwandelnde“."],
  "Александър Македонски": ["Geboren in Pella in Makedonien, Schüler des Aristoteles. Mit 20 wurde er König und eroberte in 11 Jahren das Perserreich bis nach Indien, ohne eine Schlacht zu verlieren. Er starb mit 32 in Babylon an Fieber.", "Er gründete etwa 20 Städte namens Alexandria; die berühmteste liegt in Ägypten.", "Als Junge zähmte er das Pferd Bukephalos: Er merkte, dass es vor seinem eigenen Schatten scheute, und drehte es zur Sonne."],
  "Евклид": ["Ein Mathematiker aus Alexandria, über dessen Leben fast nichts bekannt ist. Sein Werk „Die Elemente“ fasst die ganze Geometrie seiner Zeit in 13 Bänden zusammen. Über 2000 Jahre lang lernte man daraus Mathematik.", "Als König Ptolemaios einen leichteren Weg zur Geometrie wollte, antwortete er: „Es gibt keinen Königsweg zur Geometrie.“", "Nach der Bibel sind „Die Elemente“ wohl das meistgedruckte Buch der Geschichte."],
  "Ашока": ["Ein Kaiser der Maurya-Dynastie, der fast ganz Indien beherrschte. Nach dem blutigen Krieg gegen Kalinga bereute er, wurde Buddhist und predigte Gewaltlosigkeit. Er ließ seine Gesetze in Steinsäulen im ganzen Reich meißeln und starb mit etwa 72.", "Die Löwen seiner Säule in Sarnath sind das Staatswappen Indiens.", "Das Rad seiner Säulen steht in der Mitte der indischen Flagge."],
  "Архимед": ["Ein Gelehrter aus Syrakus auf Sizilien, einer der größten Mathematiker aller Zeiten. Er fand das Gesetz der schwimmenden Körper und erfand Maschinen zur Verteidigung seiner Stadt. Mit 75 wurde er von einem römischen Soldaten getötet, als die Römer Syrakus einnahmen.", "Der Sage nach fand er sein Gesetz in der Badewanne und lief „Heureka!“ – „Ich hab’s gefunden!“ – rufend durch die Straßen.", "Seine letzten Worte an den Soldaten sollen gewesen sein: „Störe meine Kreise nicht!“"],
  "Цин Шъхуан": ["Mit 13 wurde er König und einte mit 38 China als sein erster Kaiser. Er führte eine Schrift, ein Geld und ein Maß für das ganze Land ein und begann die Große Mauer. Er starb mit 49, vermutlich vergiftet von Quecksilberpillen, die ihn unsterblich machen sollten.", "Er wurde mit der Terrakotta-Armee begraben, etwa 8000 Tonsoldaten, jeder mit einem anderen Gesicht.", "Die Armee wurde 1974 zufällig von Bauern entdeckt, die einen Brunnen gruben."],
  "Ханибал": ["Ein Feldherr Karthagos, der als Junge Rom ewige Feindschaft schwor. Er überquerte mit einem Heer und Kriegselefanten die Alpen und schlug die Römer bei Cannae. Am Ende wurde er besiegt und nahm mit etwa 64 Gift, um nicht in römische Hände zu fallen.", "Lange erschreckten die Römer ihre Kinder mit „Hannibal ante portas!“ – „Hannibal vor den Toren!“.", "Von den etwa 37 Elefanten, mit denen er über die Alpen zog, überlebten nur sehr wenige."],
  "Спартак": ["Ein Thraker, wohl aus dem Gebiet des heutigen Bulgarien, gefangen und in Rom als Gladiator verkauft. 73 v. Chr. floh er aus der Gladiatorenschule und führte den größten Sklavenaufstand gegen Rom mit Zehntausenden Anhängern. Er fiel mit etwa 40 in der Schlacht.", "Sein Denkmal steht im bulgarischen Sandanski, wo er der Überlieferung nach geboren wurde.", "Seine Sklaven besiegten mehrere römische Heere, bevor Rom Marcus Crassus gegen sie schickte."],
  "Цицерон": ["Der größte Redner Roms, Konsul und Verteidiger der Republik. Nach Caesars Ermordung griff er Marcus Antonius in feurigen Reden an. Mit 63 wurde er auf Befehl des Antonius getötet.", "Hunderte seiner Briefe sind erhalten; aus ihnen wissen wir, wie die Römer im Alltag lebten.", "Er prägte die lateinischen Wörter „qualitas“ und „moralis“, die heute in vielen Sprachen weiterleben, etwa als „Qualität“ und „Moral“."],
  "Юлий Цезар": ["Ein römischer Feldherr, der Gallien eroberte und mit seinem Heer den Rubikon überschritt, um in Rom die Macht zu ergreifen. Er wurde Diktator auf Lebenszeit und führte den Kalender mit Schaltjahr ein. An den Iden des März 44 v. Chr. erstachen ihn Senatoren mit 23 Stichen; er war 55.", "Der Monat Juli trägt seinen Namen.", "Die Wörter „Kaiser“ und „Zar“ kommen von seinem Namen."],
  "Вергилий": ["Ein Dichter, geboren bei Mantua in Norditalien. Er schrieb die „Aeneis“, das Epos vom Trojaner Aeneas, von dessen Geschlecht die Römer abstammen. Er starb mit 50 an Fieber und wollte das Werk als unvollendet verbrennen lassen, doch Kaiser Augustus verbot es.", "Dante wählte ihn in der „Göttlichen Komödie“ zu seinem Führer durch die Hölle.", "Über 10 Jahre arbeitete er an der „Aeneis“ und hielt sie trotzdem für unfertig."],
  "Клеопатра": ["Die letzte Herrscherin des alten Ägypten, aus dem griechischen Haus der Ptolemäer. Sie verbündete sich erst mit Julius Caesar, dann mit Marcus Antonius gegen Rom. Nach ihrer Niederlage nahm sie sich mit 39 das Leben, der Sage nach durch den Biss einer Kobra.", "Sie lernte als Erste ihrer Familie Ägyptisch und sprach etwa neun Sprachen.", "Sie lebte näher an unserer Zeit als am Bau der Cheops-Pyramide."],
  "Октавиан Август": ["Großneffe und Adoptivsohn Julius Caesars. Er besiegte Antonius und Kleopatra und wurde der erste römische Kaiser. Er herrschte 41 Jahre in einem Frieden, der „Pax Romana“ heißt, und starb mit 75.", "Der Monat August trägt seinen Namen.", "Er sagte: „Ich fand Rom als Stadt aus Ziegeln vor und hinterlasse es als Stadt aus Marmor.“"],
  "Исус Христос": ["Geboren in Betlehem, wuchs er in Nazaret auf. Mit etwa 30 begann er, Nächstenliebe und Vergebung zu predigen, und sammelte Jünger um sich. Mit etwa 33 wurde er in Jerusalem gekreuzigt; Christen glauben, dass er am dritten Tag auferstand.", "Unsere Zeitrechnung zählt ab seiner Geburt, doch der Mönch, der sie berechnete, verrechnete sich um einige Jahre: Er wurde wohl um 4 v. Chr. geboren.", "Er sprach Aramäisch."],
  "Апостол Павел": ["Saulus von Tarsus verfolgte zuerst die Christen, doch auf dem Weg nach Damaskus hatte er eine Vision und wurde ihr eifrigster Prediger. Er reiste Tausende Kilometer durch Kleinasien und Griechenland und gründete Gemeinden. In Rom wurde er unter Nero enthauptet.", "Seine Briefe machen fast die Hälfte der Bücher des Neuen Testaments aus.", "Von Beruf war er Zeltmacher."],
  "Нерон": ["Mit 16 wurde er römischer Kaiser. Er liebte Gesang und Wagenrennen, und nach dem großen Brand Roms 64 beschuldigte er die Christen. Als der Senat ihn zum Feind erklärte, nahm er sich mit 30 das Leben.", "Seine letzten Worte waren: „Welch ein Künstler stirbt mit mir!“", "Dass er sang, während Rom brannte, ist eine Legende: Er war 50 km entfernt in Antium."],
  "Птолемей": ["Ein Astronom und Geograf aus Alexandria. Er beschrieb die Welt mit der Erde in der Mitte und Sonne und Planeten darum, ein Bild, an das man etwa 1400 Jahre glaubte. Er starb mit etwa 70.", "48 der Sternbilder, die er beschrieb, werden bis heute verwendet.", "Seine Karten machten die Erde kleiner, als sie ist; deshalb glaubte Kolumbus, Indien sei nah."],
  "Марк Аврелий": ["Ein römischer Kaiser und stoischer Philosoph. Einen Großteil seiner Herrschaft verbrachte er in Kriegen an der Donau, und dort schrieb er für sich die „Selbstbetrachtungen“. Er starb mit 58 auf einem Feldzug, vermutlich an der Pest.", "Sein bronzenes Reiterstandbild blieb erhalten, weil man es lange für Konstantin den Großen hielt.", "Er schrieb die „Selbstbetrachtungen“ auf Griechisch, nicht auf Latein."],
  "Константин Велики": ["Geboren in Naissus, dem heutigen Niš. Der erste römische Kaiser, der sich dem Christentum zuwandte: Mit dem Mailänder Edikt von 313 gab er den Christen Freiheit. Er gründete Konstantinopel und starb mit 65, auf dem Sterbebett getauft.", "Er liebte Serdica, das heutige Sofia, und soll es „mein Rom“ genannt haben.", "Vor einer entscheidenden Schlacht sah er ein Kreuz am Himmel mit den Worten „In diesem Zeichen wirst du siegen“."],
  "Свети Августин": ["Geboren in Thagaste im heutigen Algerien. Er hatte eine wilde Jugend, wurde aber mit 32 Christ und später Bischof von Hippo. Er starb mit 75, während die Vandalen die Stadt belagerten.", "Seine „Bekenntnisse“ sind vielleicht die erste Autobiografie der Geschichte.", "Als junger Mann betete er: „Herr, gib mir Keuschheit – aber noch nicht jetzt.“"],
  "Хипатия": ["Eine Mathematikerin, Astronomin und Philosophin aus Alexandria, Tochter des Mathematikers Theon. Sie lehrte öffentlich vor Männern und Frauen und wurde in der ganzen Stadt geachtet. Mit etwa 55 wurde sie von einer aufgebrachten Menge getötet.", "Sie ist die erste Mathematikerin, über deren Leben wir genug wissen.", "Der Film „Agora“ von 2009 erzählt ihre Geschichte."],
  "Атила": ["König der Hunnen, „Geißel Gottes“ genannt. Er verwüstete den Balkan, darunter Serdica, dann Gallien und Italien. Er starb mit 47 in seiner Hochzeitsnacht an starkem Nasenbluten.", "Papst Leo I. überredete ihn, Rom nicht anzugreifen.", "Er wurde in drei Särgen aus Gold, Silber und Eisen begraben, und sein Grab wurde nie gefunden."],
  "Юстиниан I": ["Ein byzantinischer Kaiser, geboren in einem Dorf beim heutigen Skopje. Er baute die Hagia Sophia in Konstantinopel und fasste die römischen Gesetze in einem Werk zusammen. Er herrschte 38 Jahre und starb mit 83.", "Seine Gesetze sind bis heute die Grundlage des Rechts in halb Europa.", "Seine Frau Theodora, eine frühere Schauspielerin, war seine engste Beraterin."],
  "Мохамед": ["Geboren in Mekka, wurde er früh Waise und Kaufmann. Mit 40 empfing er nach islamischer Lehre in einer Höhle bei Mekka die erste Offenbarung. Er begründete den Islam und starb mit 62 in Medina.", "Der islamische Kalender beginnt mit seinem Auszug von Mekka nach Medina im Jahr 622.", "Der Überlieferung nach konnte er weder lesen noch schreiben."],
  "Хан Аспарух": ["Sohn des Khans Kubrat, der seine Bulgaren aus der Steppe an die Donau führte. 680 schlug er das byzantinische Heer am Ongal, und 681 erkannte Byzanz den neuen Staat an: Donaubulgarien. Er fiel um 700 im Kampf gegen die Chasaren.", "Bulgarien ist einer der wenigen Staaten Europas, die ihren Namen über 1300 Jahre behalten haben.", "Manche Forscher vermuten sein Grab beim Dorf Wosnessenka in der Ukraine."],
  "Карл Велики": ["König der Franken, der große Teile Westeuropas einte. Am Weihnachtstag 800 krönte ihn der Papst in Rom zum Kaiser. Er förderte Schulen und Bücher und starb mit 71 in Aachen.", "Das slawische Wort für König, „Kral“, kommt von seinem Namen.", "Er selbst konnte kaum schreiben und hatte Wachstafeln unter dem Kopfkissen, um zu üben."],
  "Хан Крум": ["Ein bulgarischer Khan, „der Schreckliche“ genannt. Er eroberte 809 Serdica und schlug 811 den byzantinischen Kaiser Nikephoros im Warbiza-Pass. Er starb mit 59 plötzlich, als er die Belagerung Konstantinopels vorbereitete.", "Aus dem Schädel des Nikephoros ließ er einen silberbeschlagenen Becher machen.", "Er ist der erste bulgarische Herrscher mit aufgeschriebenen Gesetzen: Diebstahl, Lüge und Trunkenheit wurden bestraft."],
  "Ал-Хорезми": ["Ein persischer Gelehrter im „Haus der Weisheit“ in Bagdad. Er schrieb ein Buch über das Lösen von Gleichungen und verbreitete die indischen Ziffern mit der Null. Er starb mit etwa 70.", "Das Wort „Algebra“ kommt vom Titel seines Buches („al-dschabr“).", "Das Wort „Algorithmus“ kommt von seinem Namen."],
  "Свети Методий": ["Der ältere Bruder von Konstantin-Kyrill, geboren in Thessaloniki. Bevor er Mönch wurde, verwaltete er eine slawische Provinz von Byzanz. Die beiden gingen nach Großmähren; nach Kyrills Tod wurde er Erzbischof und starb dort 885 mit etwa 70.", "Deutsche Bischöfe hielten ihn zweieinhalb Jahre gefangen, weil er Gottesdienste auf Slawisch hielt.", "Der Überlieferung nach übersetzte er fast die ganze Bibel in sechs Monaten."],
  "Свети Кирил": ["Geboren in Thessaloniki als Konstantin, wegen seiner Gelehrsamkeit „der Philosoph“ genannt. Um 855–863 schuf er die Glagoliza, das erste slawische Alphabet, und übersetzte mit seinem Bruder Method die Kirchenbücher. Er starb mit 42 in Rom als Mönch namens Kyrill.", "Das kyrillische Alphabet trägt seinen Namen, wurde aber später von seinen Schülern in Bulgarien geschaffen.", "Er sprach viele Sprachen und stritt mit Arabern und Chasaren über den Glauben."],
  "Цар Борис I": ["Er taufte Bulgarien 864 und nahm den Namen Michael an. Er nahm die Schüler von Kyrill und Method, Kliment und Naum, auf, und mit ihnen wurde Bulgarien zum Zentrum des slawischen Schrifttums. Er zog sich in ein Kloster zurück und starb dort mit 72; er wird als Heiliger verehrt.", "Er verließ das Kloster, um seinen Sohn Wladimir zu stürzen, der die alten Götter zurückbringen wollte, und setzte Simeon auf den Thron.", "893 wurde Slawisch Amtssprache in Kirche und Staat."],
  "Алфред Велики": ["König von Wessex in England, der den Einfall der Wikinger aufhielt. Er baute befestigte Städte und ließ wichtige Bücher ins Englische übersetzen. Er starb mit 50 und ist der einzige englische König mit dem Beinamen „der Große“.", "Der Sage nach ließ er, als er sich vor den Wikingern in einer Hütte versteckte, die Kuchen der Hausfrau anbrennen, und sie schimpfte ihn aus, ohne zu wissen, wer er war.", "Er baute die erste englische Flotte."],
  "Цар Симеон Велики": ["Sohn Boris’ I., in Konstantinopel erzogen und deshalb „Halbgrieche“ genannt. Unter ihm erlebte Preslaw das Goldene Zeitalter des bulgarischen Schrifttums. 917 schlug er die Byzantiner am Acheloos, nahm den Zarentitel an und starb mit 63.", "Unter ihm reichte Bulgarien an drei Meere: das Schwarze, die Ägäis und die Adria.", "Eine Sage erzählt, die Byzantiner hätten einer Statue, die mit seinem Leben verbunden sein sollte, den Kopf abgeschlagen, und er sei am selben Tag gestorben."],
  "Свети Иван Рилски": ["Ein Einsiedler, der in einer Höhle und in einem hohlen Baum im Rila-Gebirge lebte. Schüler sammelten sich um ihn, und so entstand das Rila-Kloster. Er starb mit etwa 70 und ist der Schutzheilige des bulgarischen Volkes.", "Zar Peter kam, um ihn zu treffen, doch der Heilige lehnte ab; die beiden verneigten sich nur von Weitem voreinander.", "Seine Reliquien liegen bis heute im Rila-Kloster."],
  "Авицена": ["Ein persischer Arzt und Philosoph, der mit 18 alle Wissenschaften seiner Zeit beherrschte. Sein „Kanon der Medizin“ wurde etwa 600 Jahre an europäischen Universitäten gelehrt. Er schrieb rund 450 Werke und starb mit 57 an einer Krankheit.", "Mit 17 heilte er den Emir und durfte dafür die königliche Bibliothek benutzen.", "Er beschrieb als einer der Ersten, dass sich manche Krankheiten über Wasser und Boden verbreiten."],
  "Омар Хайям": ["Ein persischer Mathematiker, Astronom und Dichter. Er schuf einen Kalender, der genauer ist als unser heutiger. Berühmt ist er für seine Vierzeiler, die Rubaiyat, über Wein, Liebe und die Kürze des Lebens. Er starb mit 83 in Nischapur.", "Er löste Gleichungen dritten Grades mithilfe der Geometrie.", "Ein Mondkrater und ein Asteroid tragen seinen Namen."],
  "Хилдегард фон Бинген": ["Eine deutsche Äbtissin, die seit ihrer Kindheit Visionen hatte. Sie schrieb über Heilpflanzen, Medizin und Natur und komponierte Musik. Sie gründete ein Kloster bei Bingen am Rhein und starb mit 81.", "Sie ist eine der ersten Komponistinnen, deren Musik wir mit Namen kennen.", "Sie erfand eine eigene Geheimsprache mit etwa 1000 Wörtern."],
  "Саладин": ["Ein kurdischer Sultan von Ägypten und Syrien. 1187 eroberte er Jerusalem von den Kreuzfahrern, verschonte aber die Bewohner. Selbst seine Feinde achteten ihn; er starb mit 55 in Damaskus an Fieber.", "Er verschenkte so viel, dass bei seinem Tod nicht einmal Geld für die Beerdigung da war.", "Als Richard Löwenherz in der Schlacht sein Pferd verlor, schickte ihm Saladin zwei."],
  "Ричард Лъвското сърце": ["König von England, der den Dritten Kreuzzug anführte. Auf dem Heimweg wurde er in Österreich gefangen genommen und gegen ein riesiges Lösegeld freigelassen. Er starb mit 41 an einem Armbrustbolzen bei einer Belagerung in Frankreich.", "Von seinen zehn Jahren als König verbrachte er nur etwa sechs Monate in England und sprach kaum Englisch.", "Er wurde auf der Burg Dürnstein an der Donau gefangen gehalten."],
  "Чингис хан": ["Geboren als Temüdschin, wuchs er nach der Ermordung seines Vaters in Armut auf. Er einte die mongolischen Stämme und wurde 1206 Großkhan. Er gründete das Reich, das bald das größte zusammenhängende Landreich der Geschichte wurde, und starb mit 65; sein Grab ist unbekannt.", "Er richtete einen Postdienst mit Reitern und Stationen im ganzen Reich ein.", "Man schätzt, dass heute Millionen Männer von ihm abstammen."],
  "Франциск от Асизи": ["Sohn eines reichen Tuchhändlers aus Assisi, der alles aufgab, um in Armut zu leben. Er gründete den Franziskanerorden und predigte Liebe zu jedem Geschöpf. Er starb mit 44.", "Er predigte den Vögeln und zähmte der Legende nach den Wolf von Gubbio.", "1223 stellte er die erste lebende Krippe auf, mit echtem Ochs und Esel."],
  "Руми": ["Ein persischer Dichter, geboren in Balch im heutigen Afghanistan. Seine Familie floh vor den Mongolen und ließ sich in Konya in der Türkei nieder. Die Freundschaft mit dem Derwisch Schams aus Täbris machte ihn zum Dichter der göttlichen Liebe. Er starb mit 66.", "Seine Anhänger gründeten den Orden der tanzenden Derwische.", "Heute ist er einer der meistverkauften Dichter in den USA."],
  "Тома Аквински": ["Ein italienischer Dominikaner, der die Lehre des Aristoteles mit dem Christentum verband. Er schrieb die gewaltige „Summa theologiae“. Er starb mit 49 auf dem Weg zu einem Konzil in Lyon.", "Seine Familie sperrte ihn ein Jahr in eine Burg, damit er nicht Mönch wird; es half nichts.", "Seine Mitstudenten nannten ihn „den stummen Ochsen“, weil er groß und schweigsam war."],
  "Марко Поло": ["Ein Venezianer, der mit 17 mit Vater und Onkel nach China aufbrach. Er diente 17 Jahre Kublai Khan und reiste durch ganz Asien. Seine Reisen erzählte er in einem Gefängnis in Genua und starb mit 69 in Venedig.", "Auf dem Sterbebett sagte er: „Ich habe nicht die Hälfte von dem erzählt, was ich gesehen habe.“", "Seine Berichte von Papiergeld und schwarzen Steinen, die brennen (Kohle), erstaunten Europa."],
  "Данте Алигиери": ["Ein Dichter aus Florenz, Verfasser der „Göttlichen Komödie“, einer Reise durch Hölle, Fegefeuer und Paradies. Er schrieb sie nicht auf Latein, sondern in der toskanischen Volkssprache, und prägte so das Italienische. Für immer aus Florenz verbannt, starb er mit 56 in Ravenna an Malaria.", "Wäre er nach Florenz zurückgekehrt, hätte man ihn verbrannt.", "Durchs Paradies führt ihn Beatrice, das Mädchen, das er seit seinem neunten Lebensjahr liebte."],
  "Йоханес Гутенберг": ["Ein Goldschmied aus Mainz, der um 1450 den Buchdruck mit beweglichen Metalllettern erfand. Er druckte etwa 180 Bibeln, von denen 49 erhalten sind. Er ging pleite, verlor seine Werkstatt an seinen Geldgeber und starb mit 68.", "Bücher wurden erschwinglich, und Wissen verbreitete sich schneller als je zuvor.", "Im Alter gab ihm der Erzbischof eine Rente: jedes Jahr Kleidung, Getreide und Wein."],
  "Жана д’Арк": ["Ein Bauernmädchen aus Domrémy, das die Stimmen von Heiligen hörte. Mit 17 führte sie das französische Heer, befreite das belagerte Orléans und brachte Karl VII. zur Krönung. Sie wurde gefangen genommen und mit 19 in Rouen auf dem Scheiterhaufen verbrannt.", "Sie konnte nicht lesen und unterschrieb mit einem Kreuz.", "25 Jahre nach ihrem Tod wurde sie für unschuldig erklärt, 1920 heiliggesprochen."],
  "Христофор Колумб": ["Ein Seefahrer aus Genua, der Asien erreichen wollte, indem er nach Westen segelte. 1492 erreichte er mit drei Schiffen die Bahamas. Er unternahm vier Fahrten und starb mit 54 in der Überzeugung, in Asien gewesen zu sein.", "Amerika ist nicht nach ihm benannt, sondern nach Amerigo Vespucci.", "Seine Gebeine wurden so oft umgebettet, dass sowohl Sevilla als auch Santo Domingo sie für sich beanspruchen."],
  "Леонардо да Винчи": ["Geboren in Vinci bei Florenz, Maler der „Mona Lisa“ und des „Abendmahls“. In seinen Notizbüchern zeichnete er Flugmaschinen, Panzer und das Innere des menschlichen Körpers. Er starb mit 67 in Frankreich, am Hof König Franz’ I.", "Er war Linkshänder und schrieb in Spiegelschrift, von rechts nach links.", "Die „Mona Lisa“ behielt er bis an sein Lebensende bei sich."],
  "Албрехт Дюрер": ["Ein Maler und Kupferstecher aus Nürnberg, der größte deutsche Meister seiner Zeit. Berühmt sind seine Selbstbildnisse, die „Betenden Hände“ und der „Feldhase“. Er starb mit 56 in seiner Heimatstadt.", "Er war der erste Künstler, der seine Werke mit einem Zeichen, „AD“, wie mit einer Marke signierte.", "Sein berühmtes Nashorn schuf er, ohne je eines gesehen zu haben, nur nach der Beschreibung in einem Brief."],
  "Николай Коперник": ["Geboren in Thorn in Polen. Er zeigte, dass Erde und Planeten um die Sonne kreisen und nicht umgekehrt. Sein Buch erschien in seinem Todesjahr, mit 70; der Legende nach sah er das erste Exemplar auf dem Sterbebett.", "Er war nicht nur Astronom, sondern auch Arzt und schrieb über das Geld.", "Sein Grab wurde 2005 gefunden und mit der DNA eines Haares aus einem seiner Bücher erkannt."],
  "Микеланджело": ["Bildhauer, Maler und Baumeister, geboren in Caprese in der Toskana. Mit 26 begann er den „David“, später bemalte er die Decke der Sixtinischen Kapelle. Er entwarf die Kuppel des Petersdoms und starb mit 88 in Rom.", "Er malte die Decke etwa vier Jahre lang stehend auf einem Gerüst, den Kopf in den Nacken gelegt.", "Nach seinem Tod wurde sein Leichnam heimlich aus Rom gebracht, um in Florenz begraben zu werden."],
  "Мартин Лутер": ["Mönch und Professor in Wittenberg, geboren in Eisleben. 1517 veröffentlichte er 95 Thesen gegen den Ablasshandel, und so begann die Reformation. Er übersetzte die Bibel ins Deutsche und starb mit 62 in der Stadt, in der er geboren war.", "Er wurde Mönch nach einem Gelübde in einem schweren Gewitter, als neben ihm ein Blitz einschlug.", "Seine Übersetzung prägte die heutige deutsche Sprache."],
  "Рафаел": ["Ein Maler aus Urbino, einer der drei großen Meister der Renaissance. Er malte die „Schule von Athen“ im Vatikan und die „Sixtinische Madonna“. Er starb mit 37, genau an seinem Geburtstag.", "Die zwei kleinen Engel am unteren Rand der „Sixtinischen Madonna“ gehören zu den meistkopierten Bildern der Welt.", "Er ist im Pantheon in Rom begraben."],
  "Хенри VIII": ["König von England, berühmt für seine sechs Ehefrauen: Von zweien ließ er sich scheiden, zwei ließ er hinrichten. Er brach mit dem Papst und gründete die Kirche von England. Er starb mit 55, krank und sehr dick.", "An seinen Rüstungen sieht man, wie sein Bauch mit den Jahren wuchs.", "Der Papst verlieh ihm für ein Buch gegen Luther den Titel „Verteidiger des Glaubens“, dessen Abkürzung bis heute auf britischen Münzen steht."],
  "Сюлейман Великолепни": ["Ein osmanischer Sultan, der 46 Jahre herrschte, als das Reich auf seinem Höhepunkt war. Er belagerte 1529 Wien und erließ so viele Gesetze, dass die Türken ihn Kanuni nennen, den Gesetzgeber. Er starb mit 71 während einer Belagerung in Ungarn.", "Sein Tod wurde wochenlang geheim gehalten, damit das Heer nicht zerfiel.", "Er heiratete Hürrem, eine frühere Sklavin, die eine der mächtigsten Frauen des Reiches wurde."],
  "Елизабет I": ["Tochter Heinrichs VIII. und Anne Boleyns, die ihr Vater hinrichten ließ. Sie heiratete nie und sagte, sie sei mit England verheiratet. Unter ihr besiegte England die spanische Armada, und Shakespeares Theater blühte. Sie starb mit 69.", "Der US-Bundesstaat Virginia ist nach ihr benannt, der „jungfräulichen Königin“.", "Sie sprach mehrere Sprachen und übersetzte Bücher aus dem Lateinischen und Griechischen."],
  "Мигел де Сервантес": ["Ein spanischer Schriftsteller, der als Soldat in der Schlacht von Lepanto den Gebrauch seiner linken Hand verlor. Piraten nahmen ihn gefangen, und er war fünf Jahre Sklave in Algier. Spät im Leben schrieb er den „Don Quijote“, den ersten modernen Roman, und starb mit 68 in Madrid.", "Er starb fast zur selben Zeit wie Shakespeare; deshalb ist der 23. April Welttag des Buches.", "Viermal versuchte er, aus der Sklaverei zu fliehen."],
  "Уилям Шекспир": ["Geboren in Stratford-upon-Avon, Schauspieler und Dramatiker in London. Er schrieb etwa 39 Stücke, darunter „Hamlet“ und „Romeo und Julia“, und 154 Sonette. Er starb mit 52, wahrscheinlich an seinem Geburtstag.", "Er erfand über 1700 Wörter, die bis heute im Englischen leben.", "In seinem Testament vermachte er seiner Frau sein „zweitbestes Bett“."],
  "Галилео Галилей": ["Ein Gelehrter aus Pisa, der das Fernrohr verbesserte und die Jupitermonde und die Berge des Mondes entdeckte. Er unterstützte Kopernikus, wurde 1633 von der Inquisition verurteilt und stand bis an sein Lebensende unter Hausarrest. Er erblindete und starb mit 77.", "Der Legende nach flüsterte er nach dem Urteil: „Und sie bewegt sich doch!“", "Die Kirche gab ihren Irrtum erst 1992 offiziell zu."],
  "Йоханес Кеплер": ["Ein deutscher Astronom, geboren in Weil der Stadt. Als Gehilfe Tycho Brahes fand er die drei Gesetze, nach denen die Planeten auf Ellipsen um die Sonne laufen. Er starb mit 58 in Regensburg.", "Jahrelang verteidigte er seine Mutter, die als Hexe angeklagt war, und erreichte ihre Freilassung.", "Er schrieb eine der ersten Science-Fiction-Geschichten, über eine Reise zum Mond."],
  "Рене Декарт": ["Ein französischer Philosoph und Mathematiker, der lange in den Niederlanden lebte. Von ihm stammt „Ich denke, also bin ich“, und das Koordinatensystem trägt seinen Namen: kartesisch. Er ging nach Stockholm, um Königin Christina zu unterrichten, und starb dort mit 53 an einer Lungenentzündung.", "Er blieb gern lange im Bett, doch die Königin ließ ihn um 5 Uhr morgens unterrichten.", "Der Legende nach kam ihm die Idee der Koordinaten, als er eine Fliege an der Decke beobachtete."],
  "Рембранд": ["Ein niederländischer Maler aus Leiden, Meister von Licht und Schatten. Er malte die „Nachtwache“ und sein ganzes Leben lang Dutzende Selbstbildnisse. Er ging bankrott und starb arm mit 63 in Amsterdam.", "Die „Nachtwache“ ist eigentlich eine Szene am Tag; alter Firnis hat sie verdunkelt.", "Seine Selbstbildnisse zeigen, wie er Jahr für Jahr älter wird."],
  "Блез Паскал": ["Ein französischer Mathematiker und Philosoph. Mit 19 baute er eine Rechenmaschine, um seinem Vater, einem Steuereinnehmer, zu helfen. Mit Fermat begründete er die Wahrscheinlichkeitsrechnung und starb mit 39 nach langer Krankheit.", "Die Einheit des Drucks, das Pascal, und eine Programmiersprache tragen seinen Namen.", "Er gründete eine der ersten öffentlichen Verkehrslinien in Paris: Kutschen nach festem Fahrplan."],
  "Антони ван Левенхук": ["Ein Tuchhändler aus Delft, der seine Linsen selbst schliff und Hunderte Mikroskope baute. Er sah als Erster Bakterien, rote Blutkörperchen und andere „Tierchen“ im Wasser. Er starb mit 90.", "Er studierte nie und konnte kein Latein; er schrieb seine Entdeckungen auf Niederländisch.", "Wie er seine Linsen machte, hielt er geheim."],
  "Луи XIV": ["Ein französischer König, der Sonnenkönig genannt. Mit 4 Jahren wurde er König und herrschte 72 Jahre, länger als jeder andere Monarch der europäischen Geschichte. Er baute das Schloss Versailles und starb mit 76 an Wundbrand.", "Der Name „Sonne“ stammt aus einem Ballett, in dem er als junger Mann die Sonne tanzte.", "Er überlebte Sohn und Enkel, deshalb folgte ihm sein Urenkel."],
  "Исак Нютон": ["Ein englischer Gelehrter, der das Gravitationsgesetz und die drei Bewegungsgesetze fand. Er zerlegte das Licht mit einem Prisma in Farben und erfand die Infinitesimalrechnung. Er starb mit 84 und wurde in der Westminster Abbey beigesetzt.", "Die Geschichte mit dem Apfel ist zumindest halb wahr: Er erzählte sie selbst im Alter, doch der Apfel fiel ihm nicht auf den Kopf.", "Viele Jahre leitete er die englische Münze und jagte Fälscher persönlich."],
  "Петър Велики": ["Ein russischer Zar, über zwei Meter groß, der Russland europäisch machen wollte. Er reiste unerkannt durch Europa und arbeitete als Zimmermann auf niederländischen Werften. Er gründete Sankt Petersburg und starb mit 52.", "Er führte eine Bartsteuer ein: Wer einen Bart behalten wollte, musste zahlen.", "Er lernte über zehn Handwerke, auch das Zähneziehen."],
  "Антонио Вивалди": ["Ein venezianischer Komponist und Priester, wegen seiner roten Haare „der rote Priester“ genannt. Er unterrichtete Musik in einem Waisenhaus für Mädchen und schrieb „Die vier Jahreszeiten“ und etwa 500 Konzerte. Er starb arm mit 63 in Wien.", "Seine Musik war etwa 200 Jahre vergessen und wurde erst im 20. Jahrhundert wiederentdeckt.", "Die Waisenmädchen wurden ein berühmtes Orchester, das man aus ganz Europa hören kam."],
  "Йохан Себастиан Бах": ["Ein deutscher Komponist und Organist aus Eisenach, Thomaskantor in Leipzig. Er schrieb über 1000 Werke und hatte 20 Kinder. Er starb mit 65 nach einer missglückten Augenoperation.", "Als junger Mann wanderte er etwa 400 km zu Fuß, um den berühmten Organisten Buxtehude zu hören.", "Seine Musik fliegt auf der goldenen Platte der Voyager-Sonden durchs All."],
  "Георг Фридрих Хендел": ["Ein Komponist aus Halle, der den größten Teil seines Lebens in London verbrachte. Er schrieb das Oratorium „Messias“ und die „Wassermusik“, die auf einem Boot auf der Themse für den König gespielt wurde. Er erblindete und starb mit 74; er liegt in der Westminster Abbey.", "Beim „Halleluja“-Chor steht das Publikum auf, der Überlieferung nach, weil einst der König aufstand.", "Er wurde britischer Untertan, und die Engländer zählen ihn zu ihren Komponisten."],
  "Волтер": ["Ein französischer Schriftsteller und Philosoph, eigentlich François-Marie Arouet. Er verspottete scharf die Ungerechtigkeit und kämpfte für Toleranz und Meinungsfreiheit, wofür er in die Bastille kam und verbannt wurde. Er schrieb „Candide“ und starb mit 83 in Paris.", "Reich wurde er, als er mit einem Mathematiker eine Lücke in einer Staatslotterie fand und alle Lose kaufte.", "Er soll Dutzende Tassen Kaffee am Tag getrunken haben."],
  "Бенджамин Франклин": ["Geboren in Boston als 15. von 17 Kindern, Drucker, Forscher und Staatsmann. Mit einem Drachen zeigte er, dass der Blitz Elektrizität ist, und erfand den Blitzableiter und die Bifokalbrille. Als einer der Gründerväter der USA unterschrieb er die Unabhängigkeitserklärung und starb mit 84 in Philadelphia.", "Sein Gesicht ist auf dem 100-Dollar-Schein.", "Er ließ seine Erfindungen nie patentieren; sie sollten allen nützen."],
  "Карл Линей": ["Ein schwedischer Naturforscher, der Pflanzen und Tiere ordnete und jeder Art zwei lateinische Namen gab, etwa Homo sapiens. Er beschrieb Tausende Arten und lehrte Studenten, die in alle Welt reisten. Er starb mit 70 in Uppsala.", "Er erdachte eine „Blumenuhr“ aus Blumen, die sich zu verschiedenen Tageszeiten öffnen.", "Er wurde geadelt und hieß fortan Carl von Linné."],
  "Фридрих Велики": ["König von Preußen, der Flöte spielte, Musik schrieb und mit Voltaire befreundet war. Er führte den Siebenjährigen Krieg und machte Preußen zur Großmacht. Er starb mit 74 in Schloss Sanssouci bei Potsdam.", "Er brachte die Bauern mit einer List zum Kartoffelanbau: Er ließ seine eigenen Felder von Soldaten bewachen, damit sie wertvoll wirkten.", "Er wollte bei seinen Hunden begraben werden; erst 1991 geschah das. Heute legen Besucher Kartoffeln auf sein Grab."],
  "Мария Терезия": ["Die einzige Frau, die die habsburgischen Länder regierte. Sie führte 1774 die allgemeine Schulpflicht ein und reformierte den Staat. Sie hatte 16 Kinder, darunter die französische Königin Marie Antoinette, und starb mit 63 in Wien.", "Der Maria-Theresien-Taler wurde auch nach ihrem Tod geprägt und diente in Afrika und Arabien bis ins 20. Jahrhundert als Geld.", "Sie schrieb ihren Kindern Tausende Briefe mit mütterlichen Ratschlägen."],
  "Паисий Хилендарски": ["Ein Mönch des Klosters Hilandar auf dem Berg Athos, geboren in Bansko. 1762 vollendete er seine „Slawobulgarische Geschichte“, um den Bulgaren zu zeigen, dass sie eine ruhmreiche Vergangenheit haben, und sie aufzurufen, sich ihrer Sprache nicht zu schämen. Er starb mit 51 auf einer Reise durch die bulgarischen Länder.", "„O du Unverständiger, warum schämst du dich, dich Bulgare zu nennen?“ ist die berühmteste Zeile seines Buches.", "Die erste Abschrift machte Sofroni Wratschanski 1765; von da an ging das Buch von Hand zu Hand."],
  "Имануел Кант": ["Ein deutscher Philosoph aus Königsberg, der seine Heimatstadt kaum je verließ. Er schrieb die „Kritik der reinen Vernunft“ und lehrte, man solle so handeln, wie man es von allen wünschen würde. Er starb mit 79.", "Er war so pünktlich, dass die Nachbarn ihre Uhren nach seinem Spaziergang stellten.", "Nur einmal ließ er den Spaziergang aus: als er Rousseaus „Emile“ las."],
  "Екатерина Велика": ["Eine deutsche Prinzessin aus Stettin, die den späteren russischen Zaren Peter III. heiratete. Sie stürzte ihn und regierte Russland 34 Jahre lang, wobei sie das Reich bis ans Schwarze Meer ausdehnte. Sie starb mit 67.", "Sie ließ sich selbst gegen die Pocken impfen, um ihrem Volk zu zeigen, dass es ungefährlich ist.", "Ihre Gemäldesammlung war der Anfang der Eremitage."],
  "Джордж Вашингтон": ["Ein Gutsbesitzer aus Virginia, der im Unabhängigkeitskrieg das amerikanische Heer führte. Er wurde der erste Präsident der USA und lehnte eine dritte Amtszeit ab. Er starb mit 67 an einer Halsentzündung.", "Seine falschen Zähne waren nicht aus Holz, sondern aus Elfenbein, Metall und Menschenzähnen.", "Die Hauptstadt der USA trägt seinen Namen."],
  "Джеймс Уат": ["Ein schottischer Instrumentenbauer, der die Dampfmaschine mit einem getrennten Kondensator verbesserte. Seine Maschine machte die Industrielle Revolution möglich. Er starb mit 83.", "Die Einheit der Leistung, das Watt, ist nach ihm benannt.", "Er erfand die „Pferdestärke“, um zu erklären, wie stark seine Maschine ist."],
  "Жозеф-Мишел Монголфие": ["Ein französischer Papierfabrikant, der mit seinem Bruder Étienne den Heißluftballon erfand. 1783 hob ihr Ballon die ersten Lebewesen in den Himmel, bald auch die ersten Menschen. Er starb mit 69.", "Die ersten Passagiere waren ein Schaf, eine Ente und ein Hahn; alle drei landeten lebend.", "Die Idee kam ihm, als er sah, wie sich Wäsche über dem Feuer nach oben bauschte."],
  "Едуард Дженър": ["Ein englischer Landarzt, dem auffiel, dass Melkerinnen, die Kuhpocken gehabt hatten, nicht an den echten Pocken erkrankten. 1796 impfte er einen Jungen und schuf so den ersten Impfstoff. Er starb mit 73.", "Das Wort „Vakzin“ kommt vom lateinischen vacca, Kuh.", "1980 waren die Pocken dank seiner Impfung von der Welt verschwunden."],
  "Йохан Волфганг фон Гьоте": ["Ein deutscher Dichter aus Frankfurt, Verfasser des „Faust“ und der „Leiden des jungen Werthers“. Viele Jahre war er Minister in Weimar und betrieb auch Wissenschaft, etwa über Farben und Pflanzen. Er starb mit 82 in Weimar.", "Seine letzten Worte sollen gewesen sein: „Mehr Licht!“", "Nach dem „Werther“ kleideten sich junge Männer in ganz Europa wie sein Held, in blauem Frack und gelber Weste."],
  "Волфганг Амадеус Моцарт": ["Das Wunderkind aus Salzburg, das ab 5 Jahren komponierte und mit seinem Vater durch Europa reiste. Er schrieb über 600 Werke, darunter „Die Zauberflöte“ und das unvollendete „Requiem“. Er starb mit 35 in Wien.", "Mit 14 schrieb er ein ganzes geheim gehaltenes Kirchenstück aus dem Gedächtnis auf, nachdem er es nur einmal gehört hatte.", "Er liebte Billard und hatte einen Star, der den Anfang eines seiner Konzerte pfeifen konnte."],
  "Фридрих Шилер": ["Ein deutscher Dichter und Dramatiker aus Marbach, Verfasser der „Räuber“ und des „Wilhelm Tell“. Er war in Weimar eng mit Goethe befreundet. Er starb mit 45 an Tuberkulose.", "Seine „Ode an die Freude“ steht in Beethovens Neunter Sinfonie, und die Melodie ist heute die Hymne der Europäischen Union.", "Als junger Mann floh er vor dem Herzog, der ihm das Schreiben von Theaterstücken verboten hatte."],
  "Робърт Фултън": ["Ein Amerikaner, der zunächst Maler war. 1807 brachte er auf dem Hudson das erste erfolgreiche Dampfschiff, die „Clermont“, zu Wasser. Er starb mit 49 nach einer Erkältung in einem harten Winter.", "Vor dem Dampfschiff baute er für Napoleon ein U-Boot namens „Nautilus“.", "Die Leute nannten sein Dampfschiff „Fultons Torheit“ – bis es fuhr."],
  "Наполеон Бонапарт": ["Geboren auf Korsika, wurde er General und dann Kaiser der Franzosen. Er eroberte große Teile Europas und hinterließ den Code civil, Gesetze, die bis heute gelten. Nach der Niederlage bei Waterloo wurde er auf die Insel St. Helena verbannt und starb dort mit 51.", "Er war nicht klein: etwa 1,69 m, für seine Zeit durchschnittlich. Der Mythos stammt aus britischen Karikaturen.", "Sein Russlandfeldzug 1812 begann mit etwa 600 000 Soldaten; nur wenige kehrten zurück."],
  "Александър фон Хумболт": ["Ein deutscher Forscher und Entdecker aus Berlin. Fünf Jahre lang erforschte er Südamerika und stieg am Vulkan Chimborazo höher als jeder Mensch vor ihm. Er schrieb den „Kosmos“, eine Beschreibung der ganzen Natur, und starb mit 89.", "Nach ihm sind mehr Pflanzen, Tiere und Orte benannt als nach jedem anderen Menschen.", "Charles Darwin brach, von seinen Büchern begeistert, zu seiner Reise auf."],
  "Лудвиг ван Бетовен": ["Ein Komponist aus Bonn, der in Wien lebte. Mit etwa 30 begann er taub zu werden, schrieb aber seine größten Werke, darunter die Neunte Sinfonie, als er kaum noch hörte. Er starb mit 56, und etwa 20 000 Menschen kamen zu seiner Beerdigung.", "Für jede Tasse Kaffee zählte er 60 Bohnen ab.", "Die Melodie der „Ode an die Freude“ aus seiner Neunten ist die Hymne der Europäischen Union."],
  "Джейн Остин": ["Eine englische Schriftstellerin, Tochter eines Landpfarrers. Sie schrieb „Stolz und Vorurteil“ und „Verstand und Gefühl“, geistreiche Romane über Liebe und Ehe. Sie starb mit 41 in Winchester.", "Ihre Bücher erschienen ohne ihren Namen, nur „von einer Dame“.", "Ihr Gesicht ist auf der britischen 10-Pfund-Note."],
  "Карл Фридрих Гаус": ["Ein deutscher Mathematiker aus Braunschweig, „Fürst der Mathematiker“ genannt. Er arbeitete auch in Astronomie und Magnetismus und baute mit Weber einen der ersten elektrischen Telegrafen. Er starb mit 77 in Göttingen.", "Als Schüler addierte er die Zahlen von 1 bis 100 in Sekunden: 50 Paare zu je 101.", "Seine Glockenkurve und sein Gesicht waren auf dem alten 10-Mark-Schein."],
  "Джордж Стивънсън": ["Ein englischer Bergmannssohn, der erst mit 18 lesen lernte. Er baute die ersten richtigen Eisenbahnen und mit seinem Sohn Robert die Lokomotive „Rocket“. Man nennt ihn den „Vater der Eisenbahn“; er starb mit 67.", "Die Spurweite, die er wählte, 1435 mm, ist bis heute in den meisten Ländern Standard.", "Er lernte abends, nachdem er den ganzen Tag im Bergwerk gearbeitet hatte."],
  "Якоб Грим": ["Ein deutscher Sprachforscher aus Hanau, der mit seinem Bruder Wilhelm Volksmärchen sammelte. Darunter sind „Schneewittchen“, „Aschenputtel“ und „Hänsel und Gretel“. Er begann das gewaltige Deutsche Wörterbuch und starb mit 78 in Berlin.", "Das Wörterbuch, das die Brüder begannen, wurde erst 1961 fertig.", "Beide wurden als Teil der „Göttinger Sieben“ entlassen, weil sie gegen den König protestierten."],
  "Луи Дагер": ["Ein französischer Theatermaler, der die Daguerreotypie erfand, das erste brauchbare Fotoverfahren. 1839 schenkte Frankreich die Erfindung der ganzen Welt. Er starb mit 63.", "Auf einem seiner ersten Fotos einer Pariser Straße ist ein einziger Mensch zu sehen: Er stand still, während ihm die Schuhe geputzt wurden.", "Vor der Fotografie machte er „Dioramen“, riesige Bilder, die sich mit dem Licht veränderten."],
  "Лорд Байрон": ["Ein englischer Dichter, Verfasser von „Don Juan“ und „Childe Harold“, berühmt auch für seine Skandale. Er verließ England und kämpfte für die Freiheit Griechenlands. Er starb mit 36 an Fieber in Missolonghi und ist in Griechenland ein Nationalheld.", "In Cambridge waren Hunde verboten, also hielt er sich einen Bären.", "Er war der Vater von Ada Lovelace, der ersten Programmiererin."],
  "Самюъл Морз": ["Ein amerikanischer Maler, der Erfinder wurde. Er schuf den elektrischen Telegrafen und das nach ihm benannte Alphabet aus Punkten und Strichen. Seine erste Nachricht 1844 lautete: „Was hat Gott gewirkt“. Er starb mit 80.", "Die Idee kam ihm, nachdem seine Frau gestorben war, während er fort war, und die Nachricht ihn zu spät erreichte.", "„SOS“ ist im Morsealphabet drei Punkte, drei Striche, drei Punkte."],
  "Майкъл Фарадей": ["Sohn eines Schmieds aus London, fast ohne Schulbildung: Er lernte Buchbinder und las die Bücher, die er band. Er entdeckte die elektromagnetische Induktion und baute den ersten Elektromotor und Dynamo. Er starb mit 75.", "Er begann Weihnachtsvorlesungen für Kinder, die bis heute stattfinden.", "Er lehnte den Adelstitel ab; er wollte „einfach Mr. Faraday“ bleiben."],
  "Франц Шуберт": ["Ein Wiener Komponist, der über 600 Lieder schrieb, darunter den „Erlkönig“, mit 17 komponiert. Er lebte arm, und seine Freunde veranstalteten Abende mit seiner Musik, die „Schubertiaden“. Er starb mit 31 und wurde, wie er wollte, in der Nähe Beethovens begraben.", "An manchen Tagen schrieb er acht Lieder.", "Seine „Unvollendete“ Sinfonie hat nur zwei Sätze."],
  "Александър Пушкин": ["Ein russischer Dichter aus Moskau, Begründer der modernen russischen Literatur und Verfasser des „Eugen Onegin“. Wegen seiner freiheitlichen Verse wurde er in den Süden verbannt. Er starb mit 37 nach einem Duell um die Ehre seiner Frau.", "Sein Urgroßvater war Afrikaner: Abram Gannibal, Patensohn Peters des Großen.", "Er schrieb auch Märchen in Versen, etwa „Das Märchen vom Fischer und dem Fischlein“."],
  "Виктор Юго": ["Ein französischer Schriftsteller aus Besançon, Verfasser von „Die Elenden“ und „Der Glöckner von Notre-Dame“. Weil er sich Napoleon III. widersetzte, lebte er 19 Jahre im Exil auf der Insel Guernsey. Er starb mit 83, und etwa zwei Millionen Menschen kamen zu seinem Begräbnis.", "Nach dem Erscheinen der „Elenden“ schrieb er seinem Verleger nur „?“, und die Antwort war nur „!“.", "Sein Roman über Notre-Dame half, die Kathedrale vor dem Abriss zu retten."],
  "Юстус фон Либих": ["Ein deutscher Chemiker aus Darmstadt, der erkannte, dass Pflanzen Mineralstoffe brauchen, und so den Kunstdünger begründete. Er führte den Unterricht im Labor ein, nach dem Chemiker aus aller Welt lernten. Er starb mit 69 in München.", "Als Apothekerlehrling wurde er nach einer Explosion fortgeschickt.", "Er erfand „Liebigs Fleischextrakt“, zu dem es berühmte Sammelbilder gab."],
  "Чарлз Дарвин": ["Ein englischer Naturforscher, der fünf Jahre mit der „Beagle“ um die Welt segelte. 1859 veröffentlichte er „Über die Entstehung der Arten“ und erklärte, wie sich Lebewesen durch natürliche Auslese verändern. Er starb mit 73 und wurde in der Westminster Abbey beigesetzt.", "Die Schildkröten und Finken der Galapagosinseln brachten ihn auf die Idee.", "Er erforschte jahrzehntelang Regenwürmer und schrieb ein ganzes Buch über sie."],
  "Ейбрахам Линкълн": ["Geboren in einer Blockhütte in Kentucky, brachte er sich selbst das Anwaltswissen bei. Als 16. Präsident der USA führte er das Land durch den Bürgerkrieg und schaffte die Sklaverei ab. Mit 56 wurde er im Ford’s Theatre in Washington erschossen.", "Mit 1,93 m war er der größte Präsident der USA.", "Er ist der einzige Präsident mit einem Patent, für eine Vorrichtung, die Boote über Untiefen hebt."],
  "Фредерик Шопен": ["Ein polnischer Komponist und Pianist, geboren bei Warschau, „Poet des Klaviers“ genannt. Mit 20 verließ er Polen und lebte in Paris, wo er mit der Schriftstellerin George Sand zusammen war. Er starb mit 39 an Tuberkulose.", "Sein Herz wurde in einem Gefäß mit Cognac nach Warschau gebracht und in der Heilig-Kreuz-Kirche eingemauert.", "Sein erstes Konzert gab er mit 7."],
  "Чарлз Дикенс": ["Ein englischer Schriftsteller, der als Kind in einer Schuhcremefabrik arbeitete, während sein Vater im Schuldgefängnis saß. Er schrieb „Oliver Twist“, „David Copperfield“ und „Eine Weihnachtsgeschichte“. Er starb mit 58.", "„Eine Weihnachtsgeschichte“ prägte, wie wir bis heute Weihnachten feiern.", "Seine Romane erschienen in Fortsetzungen, und in Amerika warteten die Leute am Hafen auf das Schiff mit dem nächsten Teil."],
  "Рихард Вагнер": ["Ein deutscher Komponist aus Leipzig, Schöpfer des gewaltigen Opernzyklus „Der Ring des Nibelungen“, etwa 15 Stunden Musik. Mit Hilfe König Ludwigs II. von Bayern baute er sein eigenes Festspielhaus in Bayreuth. Er starb mit 69 in Venedig.", "Der Brautchor aus seinem „Lohengrin“ erklingt auf Hochzeiten in aller Welt.", "Er floh vor seinen Gläubigern per Schiff durch einen schweren Sturm, der ihn zum „Fliegenden Holländer“ inspirierte."],
  "Ада Лъвлейс": ["Eine englische Mathematikerin, Tochter des Dichters Byron. Sie schrieb Anmerkungen zu Charles Babbages „Analytischer Maschine“ und darin das erste Computerprogramm. Sie starb mit 36 und wurde neben dem Vater begraben, den sie nie gekannt hatte.", "Sie sah voraus, dass Maschinen eines Tages Musik schreiben könnten.", "Die Programmiersprache Ada ist nach ihr benannt."],
  "Ото фон Бисмарк": ["Ein preußischer Staatsmann, der „Eiserne Kanzler“ genannt. 1871 einte er Deutschland und wurde sein erster Reichskanzler. Er führte Kranken- und Rentenversicherung ein, die ersten der Welt, und starb mit 83.", "Als Student focht er etwa 25 Duelle.", "Der Bismarckhering ist nach ihm benannt."],
  "Карл Маркс": ["Ein deutscher Philosoph aus Trier. Mit Friedrich Engels schrieb er das „Kommunistische Manifest“, später „Das Kapital“. Er lebte viele Jahre arm in London und starb dort mit 64.", "Zu seiner Beerdigung kamen nur etwa 11 Menschen.", "Die letzte Zeile des Manifests lautet: „Proletarier aller Länder, vereinigt euch!“"],
  "Кралица Виктория": ["63 Jahre lang Königin von Großbritannien; ein ganzes Zeitalter trägt ihren Namen. Ihre neun Kinder heirateten in die Königshäuser Europas ein, und man nannte sie die „Großmutter Europas“. Sie starb mit 81.", "Sie machte das weiße Hochzeitskleid zur Mode.", "Nach dem Tod ihres Mannes Albert trug sie 40 Jahre lang Schwarz."],
  "Джоузеф Базалгет": ["Ein englischer Ingenieur, der nach dem „Großen Gestank“ in London 1858 die Kanalisation der Stadt baute. Über 1700 km Rohre leiteten das Schmutzwasser ab und beendeten die Cholera-Epidemien. Er starb mit 71.", "Er machte die Rohre doppelt so weit wie nötig – „wir machen das nur einmal“ –, deshalb funktioniert sein System noch heute.", "Er baute auch die Uferstraßen an der Themse."],
  "Флорънс Найтингейл": ["Eine englische Krankenschwester, benannt nach Florenz, wo sie geboren wurde. Im Krimkrieg rettete ihre Pflege Tausende verwundete Soldaten; nachts machte sie mit einer Lampe ihre Runde: „die Dame mit der Lampe“. Sie gründete die erste Schule für Krankenschwestern und starb mit 90.", "Der Internationale Tag der Pflege ist an ihrem Geburtstag, dem 12. Mai.", "Sie war auch Statistikerin und erfand eine neue Art Diagramm, um zu zeigen, woran die Soldaten starben."],
  "Георги Раковски": ["Ein Revolutionär und Schriftsteller aus Kotel, der als Erster einen organisierten Kampf für die Befreiung Bulgariens plante. 1862 gründete er in Belgrad die Erste Bulgarische Legion. Er starb mit 46 an Tuberkulose in Bukarest.", "Er änderte seinen Namen viele Male; geboren wurde er als Sabi Stojkow Popowitsch.", "Er schrieb das Poem „Der Waldwanderer“, einen Aufruf an die Bulgaren, sich zu erheben."],
  "Фьодор Достоевски": ["Ein russischer Schriftsteller aus Moskau, Verfasser von „Schuld und Sühne“, „Der Idiot“ und „Die Brüder Karamasow“. 1849 wurde er zum Tode verurteilt, im letzten Augenblick vor dem Erschießungskommando begnadigt und verbrachte vier Jahre im Straflager in Sibirien. Er starb mit 59.", "Den „Spieler“ schrieb er in 26 Tagen, um Schulden zu bezahlen, und heiratete die Stenografin, der er ihn diktierte.", "Sein Leben lang kämpfte er mit seiner Spielsucht."],
  "Луи Пастьор": ["Ein französischer Forscher, der bewies, dass viele Krankheiten von Mikroben ausgelöst werden. Er erfand die Pasteurisierung, ein sanftes Erhitzen, das Milch und Wein haltbar macht. 1885 rettete er einen Jungen, den ein tollwütiger Hund gebissen hatte, mit dem ersten Impfstoff gegen Tollwut. Er starb mit 72.", "Drei seiner fünf Kinder starben an Typhus; das trieb ihn an, Krankheiten zu bekämpfen.", "Der gerettete Junge, Joseph Meister, wurde später Hausmeister im Institut Pasteur."],
  "Грегор Мендел": ["Ein Mönch in einem Kloster in Brünn, geboren in Schlesien. Im Klostergarten zog er etwa 28 000 Erbsenpflanzen und entdeckte die Gesetze der Vererbung. Zu Lebzeiten verstand niemand seine Entdeckung; er starb mit 61 als Abt.", "Zweimal fiel er durch die Lehrerprüfung.", "Seine Arbeit wurde erst 1900 wiederentdeckt, und er wurde zum „Vater der Genetik“."],
  "Лев Толстой": ["Ein russischer Schriftsteller, geboren auf dem Gut Jasnaja Poljana, Verfasser von „Krieg und Frieden“ und „Anna Karenina“. Im Alter predigte er einfaches Leben und Gewaltlosigkeit und inspirierte Gandhi. Mit 82 verließ er heimlich sein Haus und starb auf einem kleinen Bahnhof.", "Seine Frau schrieb „Krieg und Frieden“ etwa siebenmal mit der Hand ab.", "„Krieg und Frieden“ hat etwa 580 Figuren."],
  "Дмитрий Менделеев": ["Ein russischer Chemiker aus Tobolsk in Sibirien, das jüngste von vielen Kindern. 1869 ordnete er die chemischen Elemente in einer Tabelle und ließ Lücken für noch unbekannte, die dann wirklich gefunden wurden. Er starb mit 72.", "Der Legende nach sah er die Tabelle im Traum.", "Das Element Nummer 101 heißt Mendelevium."],
  "Марк Твен": ["Ein amerikanischer Schriftsteller, eigentlich Samuel Clemens, der am Ufer des Mississippi aufwuchs. Er war Lotse auf einem Raddampfer und schrieb dann „Die Abenteuer des Tom Sawyer“ und „Huckleberry Finn“. Er starb mit 74.", "Er wurde in einem Jahr des Halleyschen Kometen geboren, sagte voraus, er werde mit ihm gehen, und starb bei seiner Wiederkehr 1910.", "„Mark twain“ war der Ruf der Flusslotsen für eine Wassertiefe von zwei Faden."],
  "Васил Левски": ["Geboren in Karlowo als Wassil Kuntschew, ein früherer Mönch, „der Diakon“ genannt. Er zog durchs Land und baute ein Netz geheimer Revolutionskomitees für die Befreiung Bulgariens auf. Er wurde bei Lowetsch gefasst und mit 35 in Sofia gehängt.", "Man nennt ihn den „Apostel der Freiheit“.", "Den Beinamen „Lewski“, „der Löwenhafte“, bekam er, weil er wie ein Löwe sprang."],
  "Пьотр Чайковски": ["Ein russischer Komponist, Schöpfer der Ballette „Schwanensee“, „Der Nussknacker“ und „Dornröschen“. 13 Jahre lang unterstützte ihn eine reiche Verehrerin mit Geld; sie schrieben sich nur Briefe und trafen sich nie. Er starb mit 53 in Sankt Petersburg.", "Er dirigierte 1891 bei der Eröffnung der Carnegie Hall in New York.", "Als kleiner Junge weinte er beim Hören von Musik und sagte: „Diese Musik ist in meinem Kopf und lässt mich nicht los!“"],
  "Клод Моне": ["Ein französischer Maler aus Paris, der Vater des Impressionismus. Die ganze Richtung ist nach seinem Bild „Impression, Sonnenaufgang“ benannt. In seinen letzten Jahren malte er die Seerosen in seinem Garten in Giverny und starb mit 86.", "Er malte etwa 250 Bilder von Seerosen.", "Im Alter veränderte der graue Star die Farben, die er sah, und seine Bilder wurden röter."],
  "Роберт Кох": ["Ein deutscher Arzt, der die Erreger von Milzbrand, Tuberkulose und Cholera entdeckte. 1905 erhielt er den Nobelpreis. Er starb mit 66 in Baden-Baden.", "Der Welttuberkulosetag, der 24. März, ist der Tag, an dem er seine Entdeckung bekannt gab.", "Er begann als Landarzt mit einem Mikroskop, das ihm seine Frau geschenkt hatte."],
  "Карл Бенц": ["Ein deutscher Ingenieur aus Karlsruhe, der 1886 das erste echte Automobil mit Benzinmotor patentieren ließ. Seine Firma wurde später zu Mercedes-Benz. Er starb mit 84.", "Sein Vater, ein Lokführer, starb, als Karl 2 Jahre alt war.", "Sein erstes Auto hatte nur drei Räder."],
  "Фридрих Ницше": ["Ein deutscher Philosoph, der schon mit 24 Professor in Basel wurde. Er schrieb „Also sprach Zarathustra“ und das berühmte „Gott ist tot“. 1889 brach er in Turin geistig zusammen und verbrachte seine letzten 11 Jahre krank; er starb mit 55.", "Bei seinem Zusammenbruch soll er ein Pferd umarmt haben, das auf der Straße geschlagen wurde.", "Er komponierte auch Musik."],
  "Вилхелм Рьонтген": ["Ein deutscher Physiker, der 1895 Strahlen entdeckte, die durch den Körper sehen: die Röntgenstrahlen. 1901 erhielt er den allerersten Nobelpreis für Physik. Er starb mit 77.", "Das erste Röntgenbild zeigt die Hand seiner Frau, mit ihrem Ring.", "Er ließ seine Entdeckung nicht patentieren, damit sie allen nützt."],
  "Томас Едисон": ["Ein amerikanischer Erfinder mit über 1000 Patenten: der Phonograph, die brauchbare Glühbirne, die Filmkamera und die ersten Kraftwerke. Er ging nur drei Monate zur Schule. Er starb mit 84.", "Seit seiner Jugend war er fast taub.", "Er sagte: „Genie ist ein Prozent Inspiration und neunundneunzig Prozent Transpiration.“"],
  "Христо Ботев": ["Ein Dichter und Revolutionär aus Kalofer. In Rumänien gab er Zeitungen heraus und schrieb Gedichte über die Freiheit. 1876 kaperte seine Schar den österreichischen Dampfer „Radetzky“, landete bei Kosloduj, und er fiel mit 28 im Wraza-Balkan.", "Jedes Jahr am 2. Juni um 12 Uhr heulen in Bulgarien eine Minute lang die Sirenen zu seinem Gedenken und dem aller, die für die Freiheit starben.", "Ein Nachbau des Dampfers „Radetzky“ liegt heute in Kosloduj."],
  "Берта Бенц": ["Die Frau von Karl Benz, die ihre Mitgift in sein Auto steckte. 1888 fuhr sie, ohne ihrem Mann Bescheid zu sagen, mit den beiden Söhnen die erste lange Autofahrt: 106 km von Mannheim nach Pforzheim. Sie starb mit 95.", "Unterwegs reinigte sie eine verstopfte Leitung mit einer Hutnadel und isolierte ein Kabel mit ihrem Strumpfband.", "Benzin kaufte sie in einer Apotheke in Wiesloch, die heute als erste Tankstelle der Welt gilt."],
  "Иван Вазов": ["Ein Schriftsteller aus Sopot, „Patriarch der bulgarischen Literatur“ genannt. Im Exil in Odessa schrieb er „Unter dem Joch“, den ersten bulgarischen Roman, und das „Epos der Vergessenen“. Er war auch Bildungsminister. Er starb mit 71 in Sofia.", "„Unter dem Joch“ wurde in über 30 Sprachen übersetzt.", "Er heiratete nie."],
  "Винсент ван Гог": ["Ein niederländischer Maler, der in nur etwa zehn Jahren rund 900 Bilder malte, darunter „Sonnenblumen“ und „Sternennacht“. Er lebte arm und litt unter schweren seelischen Krisen, in einer schnitt er sich einen Teil des Ohres ab. Er starb mit 37 an einer Schusswunde.", "Zu Lebzeiten verkaufte er nur ein einziges Bild.", "Er schrieb über 650 Briefe an seinen Bruder Theo, der ihn sein Leben lang unterstützte."],
  "Никола Тесла": ["Geboren in Smiljan im heutigen Kroatien. Er erfand das Wechselstromsystem, das bis heute unsere Häuser versorgt. Er starb arm und allein mit 86 in einem New Yorker Hotelzimmer.", "Die Einheit der magnetischen Flussdichte, das Tesla, ist nach ihm benannt.", "Er liebte Tauben und kümmerte sich bis an sein Lebensende um sie."],
  "Зигмунд Фройд": ["Ein österreichischer Arzt, geboren in Mähren, der in Wien lebte. Er begründete die Psychoanalyse und lehrte, dass Träume und das Unbewusste vieles in unserem Leben lenken. 1938 floh er vor den Nazis nach London und starb dort mit 83.", "Seine berühmte Couch für Patienten steht heute in seinem Londoner Museum.", "Er rauchte etwa 20 Zigarren am Tag."],
  "Макс Планк": ["Ein deutscher Physiker aus Kiel, der 1900 die Quantentheorie begründete. 1918 erhielt er den Nobelpreis. Er starb mit 89.", "Sein Lehrer riet ihm von der Physik ab, da dort „fast alles schon erforscht“ sei.", "Er war ein ausgezeichneter Pianist und musizierte oft mit Einstein."],
  "Алеко Константинов": ["Ein Schriftsteller aus Swischtow, „der Glückliche“ genannt. Er erschuf Baj Ganjo und schrieb den Reisebericht „Nach Chicago und zurück“ nach dem Besuch der Weltausstellung. Mit 34 wurde er bei Pasardschik versehentlich erschossen; die Kugel galt einem anderen.", "1895 führte er etwa 300 Menschen auf den Tscherni Wrach und begründete so das organisierte Wandern in Bulgarien.", "Baj Ganjo wurde so bekannt, dass sein Name bis heute für einen bestimmten Menschentyp steht."],
  "Мария Кюри": ["Geboren in Warschau, entdeckte sie mit ihrem Mann Pierre Polonium und Radium. Sie war die erste Frau mit einem Nobelpreis und ist der einzige Mensch mit Nobelpreisen in zwei verschiedenen Wissenschaften, Physik und Chemie. Sie starb mit 66 an einer Krankheit, die die Strahlung verursacht hatte, mit der sie arbeitete.", "Polonium benannte sie nach ihrer Heimat Polen.", "Ihre Notizbücher sind bis heute radioaktiv und werden in Bleikisten aufbewahrt."],
  "Махатма Ганди": ["Ein indischer Anwalt, der in Südafrika und dann in Indien gewaltlos gegen Unrecht kämpfte. 1930 ging er auf dem „Salzmarsch“ 385 km zu Fuß ans Meer. 1947 wurde Indien unabhängig, und im Jahr darauf wurde er mit 78 ermordet.", "Er wurde fünfmal für den Friedensnobelpreis nominiert, bekam ihn aber nie.", "Den Stoff für seine Kleidung spann er selbst."],
  "Орвил Райт": ["Ein Amerikaner, der mit seinem Bruder Wilbur in Dayton Fahrräder reparierte und Flugzeuge baute. Am 17. Dezember 1903 steuerte Orville den ersten gesteuerten Motorflug: 12 Sekunden und 37 Meter. Er starb mit 76.", "Neil Armstrong nahm ein Stück Stoff ihres Flugzeugs mit zum Mond.", "Keiner der beiden Brüder heiratete je."],
  "Гулиелмо Маркони": ["Ein italienischer Erfinder aus Bologna, der das Radio schuf. 1901 schickte er ein Funksignal über den Atlantik. Mit 35 erhielt er den Nobelpreis und starb mit 63.", "Die Überlebenden der „Titanic“ wurden gerettet, weil das Schiff mit seinem Funk um Hilfe rief.", "Bei seinem Tod schwiegen die Radiosender der ganzen Welt zwei Minuten lang."],
  "Уинстън Чърчил": ["Ein britischer Staatsmann, geboren im Blenheim Palace. Als Premierminister führte er Großbritannien durch den Zweiten Weltkrieg und versprach „nichts als Blut, Mühsal, Tränen und Schweiß“. Er erhielt den Literaturnobelpreis und starb mit 90.", "Als junger Reporter floh er im Burenkrieg aus der Gefangenschaft.", "Er malte etwa 500 Bilder."],
  "Томас Ман": ["Ein deutscher Schriftsteller aus Lübeck, Verfasser der „Buddenbrooks“ und des „Zauberbergs“. 1929 erhielt er den Nobelpreis. Als Gegner der Nazis emigrierte er in die USA und starb mit 80 in Zürich.", "Die „Buddenbrooks“ schrieb er mit nur 25.", "Seine ganze Familie schrieb: Auch sein Bruder Heinrich und seine Kinder Klaus und Erika waren Schriftsteller."],
  "Елин Пелин": ["Ein Schriftsteller aus dem Dorf Bajlowo, eigentlich Dimitar Iwanow Stojanow. Ein Meister der Erzählung über das Dorfleben und Verfasser der Kinderbücher über Jan Bibijan. Er starb mit 72 in Sofia.", "In der Fortsetzung fliegt Jan Bibijan bis zum Mond.", "Viele Jahre arbeitete er als Bibliothekar an der Universitätsbibliothek."],
  "Пейо Яворов": ["Ein Dichter aus Tschirpan, geboren als Pejo Kratscholow. Er kämpfte in den Freischaren in Makedonien und schrieb einige der stärksten bulgarischen Gedichte über Liebe und Trauer. Nach dem tragischen Tod seiner Frau Lora verlor er sein Augenlicht und nahm sich mit 36 das Leben.", "Den Namen „Jaworow“ nahm er vom Bergahorn, bulgarisch „jawor“.", "Er schrieb das Gedicht „Zwei schöne Augen“, das ein berühmtes Lied wurde."],
  "Алберт Айнщайн": ["Ein Physiker aus Ulm, Schöpfer der Relativitätstheorie und der Formel E = mc². 1921 erhielt er den Nobelpreis, 1933 emigrierte er in die USA. Er starb mit 76 in Princeton.", "Dass er in Mathe schlecht war, ist eine Legende.", "1952 bot man ihm das Amt des Präsidenten Israels an, doch er lehnte ab."],
  "Александър Флеминг": ["Ein schottischer Arzt und Forscher. 1928 bemerkte er nach dem Urlaub Schimmel in einer vergessenen Schale, um den herum die Bakterien abgestorben waren, und entdeckte so das Penicillin. 1945 erhielt er den Nobelpreis und starb mit 73.", "Penicillin und die Antibiotika danach haben Hunderte Millionen Leben gerettet.", "Schon vorher fand er einen keimtötenden Stoff in seinem eigenen Nasenschleim."],
  "Пабло Пикасо": ["Ein spanischer Maler aus Málaga, der mit Braque den Kubismus begründete. Er malte „Guernica“, einen Aufschrei gegen die Bombardierung einer Stadt. Er schuf etwa 50 000 Werke und starb mit 91.", "Sein erstes Wort war „piz“, von „lápiz“, Bleistift.", "Sein vollständiger Name enthält über 20 Namen von Heiligen und Verwandten."],
  "Франц Кафка": ["Ein Schriftsteller aus Prag, der auf Deutsch schrieb und als Angestellter einer Versicherung arbeitete. Verfasser der „Verwandlung“, über einen Mann, der eines Morgens als riesiges Insekt erwacht, und des „Prozesses“. Er starb mit 40 an Tuberkulose.", "Er bat seinen Freund Max Brod, alle seine Manuskripte zu verbrennen, doch Brod veröffentlichte sie.", "Von seinem Namen kommt das Wort „kafkaesk“ für eine sinnlose, beklemmende Lage."],
  "Чарли Чаплин": ["Ein Schauspieler und Regisseur, der arm in London aufwuchs. Er erschuf den Tramp mit Stöckchen und Melone, die bekannteste Figur des Stummfilms. In „Der große Diktator“ verspottete er Hitler. Er starb mit 88 in der Schweiz am Weihnachtstag.", "1978 wurde sein Sarg für ein Lösegeld gestohlen und einige Wochen später gefunden.", "Er soll einmal an einem Chaplin-Doppelgänger-Wettbewerb teilgenommen und nicht gewonnen haben."],
  "Агата Кристи": ["Eine englische Schriftstellerin aus Torquay, die meistverkaufte Romanautorin der Geschichte. Sie erfand die Detektive Hercule Poirot und Miss Marple. Ihr Stück „Die Mausefalle“ läuft seit 1952 ohne Unterbrechung. Sie starb mit 85.", "1926 verschwand sie für 11 Tage, und bis heute weiß niemand sicher, was geschah.", "Sie arbeitete in einer Krankenhausapotheke und wusste deshalb so viel über Gifte."],
  "Дж. Р. Р. Толкин": ["Geboren in Bloemfontein in Südafrika, Professor in Oxford. Er schrieb „Der Hobbit“ und „Der Herr der Ringe“ und erfand ganze Sprachen für die Elben. Er starb mit 81.", "Den ersten Satz des „Hobbit“ – „In einer Höhle in der Erde, da lebte ein Hobbit“ – kritzelte er auf ein leeres Blatt, während er Prüfungsarbeiten korrigierte.", "Als junger Mann kämpfte er im Ersten Weltkrieg in der Schlacht an der Somme."],
  "Елисавета Багряна": ["Eine Dichterin aus Sofia, eigentlich Elissaweta Beltschewa. Ihre Gedichte über Freiheit, das Meer und das Frausein machten sie zur meistgeliebten bulgarischen Dichterin. Sie starb mit 97.", "Ihr Künstlername „Bagrjana“ kommt von „bagren“, purpurrot.", "Sie wurde für den Literaturnobelpreis nominiert."],
  "Марлене Дитрих": ["Eine deutsche Schauspielerin und Sängerin aus Berlin, die mit dem Film „Der blaue Engel“ ein Star wurde. Sie lehnte es ab, für die Nazis zu arbeiten, wurde Amerikanerin und sang für Soldaten an der Front. Sie starb mit 90 in Paris.", "Ihr Lied „Lili Marleen“ liebten Soldaten auf beiden Seiten der Front.", "Sie schockierte, weil sie Hosen trug, als das für Frauen nicht üblich war."],
  "Уолт Дисни": ["Ein amerikanischer Trickfilmer aus Chicago, der 1928 Micky Maus erfand und „Schneewittchen“, den ersten abendfüllenden Zeichentrickfilm. 1955 eröffnete er Disneyland und starb mit 65.", "Er sprach Micky Maus selbst.", "Er gewann 22 Oscars, mehr als jeder andere Mensch."],
  "Джордж Оруел": ["Ein englischer Schriftsteller, geboren in Indien als Eric Blair. Er schrieb „Farm der Tiere“ und „1984“, Bücher gegen die Tyrannei. Im Spanischen Bürgerkrieg wurde er in den Hals geschossen. Er starb mit 46 an Tuberkulose.", "Der Satz „Der Große Bruder sieht dich“ stammt aus „1984“.", "„1984“ schrieb er auf einer abgelegenen schottischen Insel, schon schwer krank."],
  "Сергей Корольов": ["Ein sowjetischer Raketenkonstrukteur, geboren in Schytomyr. Als Chefkonstrukteur schickte er 1957 den ersten Satelliten und 1961 Juri Gagarin ins All. Er starb mit 59 während einer Operation.", "Solange er lebte, war sein Name Staatsgeheimnis; man nannte ihn nur „den Chefkonstrukteur“.", "Zuvor war er unschuldig jahrelang in einem sibirischen Lager."],
  "Фрида Кало": ["Eine mexikanische Malerin aus Coyoacán. Mit 18 hinterließ ihr ein Busunfall lebenslange Schmerzen, und sie begann im Bett zu malen. Die meisten ihrer Bilder sind Selbstbildnisse. Sie starb mit 47.", "Ihr Haus, das „Blaue Haus“, ist heute ein Museum.", "Ihr letztes Bild, ein Stillleben mit Wassermelonen, trägt die Worte „Viva la vida“ – „Es lebe das Leben“."],
  "Никола Вапцаров": ["Ein Dichter aus Bansko, der die Marineschule besuchte und als Heizer und Maschinist auf Schiffen arbeitete. Sein einziger Gedichtband, „Motorlieder“, handelt von der Arbeit und vom Glauben an den Menschen. Er wurde mit 32 erschossen, weil er im Widerstand war.", "Stunden vor der Hinrichtung schrieb er sein letztes Gedicht: „Der Kampf ist unerbittlich grausam“.", "Ein Gipfel in der Antarktis trägt seinen Namen."],
  "Конрад Цузе": ["Ein deutscher Ingenieur aus Berlin, der 1941 die Z3 baute, den ersten funktionierenden programmierbaren Computer. Seine ersten Maschinen baute er im Wohnzimmer seiner Eltern. Er starb mit 85.", "Er erfand auch den Plankalkül, die erste höhere Programmiersprache.", "Neben der Technik war er auch Maler."],
  "Майка Тереза": ["Geboren in Skopje als Anjezë Bojaxhiu, eine Nonne, die ihr Leben den Ärmsten in Kalkutta widmete. Sie gründete den Orden der Missionarinnen der Nächstenliebe. 1979 erhielt sie den Friedensnobelpreis und starb mit 87; sie wurde heiliggesprochen.", "Sie bat, das Nobelbankett abzusagen und das Geld den Armen zu geben.", "Sie trug einen weißen Sari mit blauen Streifen, der zum Zeichen ihres Ordens wurde."],
  "Ванга": ["Eine bulgarische Hellseherin aus Strumica, die als Kind nach einem Sturm erblindete. Sie lebte in Petritsch, wohin Zehntausende zu ihr kamen, vom Bauern bis zum Staatsmann. Sie starb 1996 mit 85.", "Der Staat zahlte ihr ein Gehalt als Mitarbeiterin eines Instituts, das ihre Fähigkeiten erforschte.", "Unter ihrem Namen kursieren viele „Prophezeiungen“, die sie nie gemacht hat."],
  "Алън Тюринг": ["Ein englischer Mathematiker, der Vater der Informatik. Er beschrieb die „Turingmaschine“, die Idee hinter dem Computer, und half im Zweiten Weltkrieg, die deutsche Chiffriermaschine Enigma zu knacken. Wegen Homosexualität verurteilt, starb er mit 41 an einer Zyankalivergiftung.", "Er erfand den „Turing-Test“: Kann eine Maschine im Gespräch als Mensch durchgehen?", "Er lief einen Marathon in 2 Stunden 46 Minuten und kam fast in die Olympiamannschaft."],
  "Вернер фон Браун": ["Ein deutscher Raketeningenieur. Er baute für NS-Deutschland die V2 und wurde nach dem Krieg in die USA gebracht, wo er die Saturn V entwarf, die Menschen zum Mond brachte. Er starb 1977 mit 65.", "Die V2 wurde von Häftlingen unter furchtbaren Bedingungen gebaut: Beim Bau starben mehr Menschen als durch ihre Einschläge.", "Als Junge band er Raketen an einen Bollerwagen und jagte ihn durch eine Berliner Straße, worauf ihn die Polizei abholte."],
  "Роза Паркс": ["Eine afroamerikanische Näherin aus Montgomery, Alabama. 1955 weigerte sie sich, ihren Sitz im Bus für einen Weißen zu räumen, und wurde verhaftet. Der folgende Busboykott wurde zum Beginn der Bürgerrechtsbewegung. Sie starb 2005 mit 92.", "Der Boykott dauerte 381 Tage, bis die Rassentrennung in Bussen verboten wurde.", "Nach ihrem Tod wurde sie im Kapitol aufgebahrt, als erste Frau überhaupt."],
  "Норман Борлоуг": ["Ein amerikanischer Agrarwissenschaftler, der Vater der „Grünen Revolution“. Er züchtete einen kurzen, robusten Weizen, der die Ernten in Mexiko, Indien und Pakistan verdoppelte und verdreifachte. 1970 erhielt er den Friedensnobelpreis, er starb mit 95.", "Seine Arbeit soll etwa eine Milliarde Menschen vor dem Hunger bewahrt haben.", "Von seinem Preis erfuhr er auf dem Feld, wohin seine Frau fuhr, um es ihm zu sagen."],
  "Нелсън Мандела": ["Ein südafrikanischer Kämpfer gegen die Apartheid. Er saß 27 Jahre im Gefängnis, wurde nach seiner Freilassung 1990 der erste schwarze Präsident Südafrikas und versöhnte das Land. Er starb 2013 mit 95.", "Die meisten Haftjahre verbrachte er auf Robben Island, wo er in einem Steinbruch Steine klopfte.", "Den Friedensnobelpreis 1993 teilte er mit Frederik de Klerk, dem Präsidenten, der ihn freiließ."],
  "Йоан Павел II": ["Karol Wojtyła, der erste polnische Papst und der erste Nichtitaliener seit 455 Jahren. Von 1978 bis 2005 Papst, bereiste er die ganze Welt und trug zum Ende des Kommunismus in Osteuropa bei. Er starb mit 84.", "1981 überlebte er ein Attentat und vergab dem Schützen später im Gefängnis.", "Als junger Mann war er Schauspieler und schrieb Theaterstücke."],
  "Софи Шол": ["Eine deutsche Studentin in München, Mitglied der „Weißen Rose“, die Flugblätter gegen Hitler verbreitete. 1943 wurde sie beim Auswerfen von Flugblättern in der Universität gefasst und mit 21 zusammen mit ihrem Bruder Hans hingerichtet.", "Zwischen Verhaftung und Hinrichtung lagen nur wenige Tage.", "Das letzte Flugblatt der Gruppe gelangte nach England, und britische Flugzeuge warfen es millionenfach über Deutschland ab."],
  "Мартин Лутър Кинг": ["Ein amerikanischer Pastor und Anführer der Bürgerrechtsbewegung. Er predigte Gewaltlosigkeit und hielt 1963 die Rede „I Have a Dream“. Er erhielt den Friedensnobelpreis und wurde 1968 mit 39 erschossen.", "Mit 35 war er der bis dahin jüngste Friedensnobelpreisträger.", "Geboren wurde er als Michael; sein Vater änderte beider Namen nach einer Deutschlandreise."],
  "Ана Франк": ["Ein jüdisches Mädchen aus Frankfurt, dessen Familie nach Amsterdam floh. Zwei Jahre versteckte sie sich mit ihnen im Hinterhaus und führte ein Tagebuch. 1944 wurden sie verraten, und sie starb mit 15 im Lager Bergen-Belsen an Typhus.", "Ihr Vater überlebte als Einziger der acht Versteckten und veröffentlichte das Tagebuch.", "Das Tagebuch bekam sie zum 13. Geburtstag und nannte es „Kitty“."],
  "Нийл Армстронг": ["Ein amerikanischer Astronaut und Testpilot. Am 20. Juli 1969 betrat er mit Apollo 11 als erster Mensch den Mond. Er starb 2012 mit 82.", "Seine ersten Worte dort: „Ein kleiner Schritt für einen Menschen, ein riesiger Sprung für die Menschheit.“", "Seine Fußspuren sind wohl noch da, denn auf dem Mond gibt es keinen Wind."],
  "Юрий Гагарин": ["Ein sowjetischer Pilot, Sohn von Kolchosbauern. Am 12. April 1961 flog er mit Wostok 1 als erster Mensch ins All und umrundete die Erde in 108 Minuten. Er starb 1968 mit 34 bei einem Übungsflug mit einem Kampfjet.", "Beim Start rief er „Pojechali!“, „Los geht’s!“", "Er landete mit dem Fallschirm auf einem Feld und erschreckte eine Bäuerin und ihre Enkelin."],
  "Елвис Пресли": ["Ein amerikanischer Sänger aus Mississippi, der „King of Rock ’n’ Roll“. Vom Lkw-Fahrer wurde er mit Liedern wie „Hound Dog“ zum größten Star der 1950er. Er starb 1977 mit 42 in seinem Haus Graceland.", "Er hatte einen Zwillingsbruder, Jesse, der bei der Geburt starb.", "Er hat über eine halbe Milliarde Tonträger verkauft."],
  "Джон Ленън": ["Ein englischer Musiker aus Liverpool, Gründer der Beatles. Nach der Trennung der Band schrieb er „Imagine“ und setzte sich mit Yoko Ono für den Frieden ein. 1980 wurde er mit 40 vor seinem Haus in New York erschossen.", "Sein Mörder hatte sich nur Stunden vorher ein Autogramm von ihm geholt.", "Seine Lehrer schrieben, er sei „auf dem Weg zum Scheitern“."],
  "Стивън Хокинг": ["Ein britischer Physiker, der Schwarze Löcher und den Anfang des Universums erforschte. Mit 21 erkrankte er an ALS und man gab ihm zwei Jahre, doch er lebte noch 55, sprechend über einen Computer. Er starb 2018 mit 76.", "Sein Buch „Eine kurze Geschichte der Zeit“ verkaufte sich über 10 Millionen Mal.", "Er wurde genau 300 Jahre nach Galileis Tod geboren und starb an Einsteins Geburtstag."],
  "Мохамед Али": ["Ein amerikanischer Boxer, geboren als Cassius Clay. Dreimal Weltmeister im Schwergewicht, berühmt für seine Schnelligkeit und den Spruch „Schwebe wie ein Schmetterling, stich wie eine Biene“. Den Kriegsdienst in Vietnam verweigerte er. Er starb 2016 mit 74.", "Mit 12 fing er mit dem Boxen an, weil man ihm das Fahrrad gestohlen hatte und er den Dieb verprügeln wollte.", "Wegen der Verweigerung verlor er den Titel und durfte fast vier Jahre nicht boxen."],
  "Фреди Меркюри": ["Sänger der britischen Band Queen, geboren als Farrokh Bulsara auf Sansibar. Er schrieb „Bohemian Rhapsody“ und „We Are the Champions“ und hatte eine Stimme über vier Oktaven. Er starb 1991 mit 45 an Aids.", "Das Wappen der Band entwarf er selbst, denn er hatte Grafikdesign studiert.", "Ihr Auftritt bei Live Aid 1985 gilt oft als bestes Live-Konzert aller Zeiten."],
  "Стив Джобс": ["Ein amerikanischer Unternehmer, der Apple mit Steve Wozniak in einer Garage gründete. Aus der eigenen Firma geworfen, kam er zurück und schuf iPod, iPhone und iPad. Er starb 2011 mit 56 an Bauchspeicheldrüsenkrebs.", "Er wurde als Baby adoptiert; sein leiblicher Vater stammte aus Syrien.", "Er kaufte ein kleines Studio, aus dem Pixar wurde, das „Toy Story“ drehte."],
  "Хатшепсут": ["Eine ägyptische Königin, die sich zum Pharao erklärte und etwa 20 Jahre in Frieden und Wohlstand herrschte. Sie baute den prächtigen Tempel von Deir el-Bahari und schickte eine Expedition ins ferne Land Punt. Sie starb mit etwa 49.", "Ihre Statuen zeigen sie oft mit dem falschen Pharaonenbart.", "Nach ihrem Tod tilgte jemand sorgfältig ihren Namen und ihre Bilder von den Denkmälern."],
  "Кир Велики": ["Gründer des Perserreichs, des bis dahin größten Reiches, vom Mittelmeer bis Indien. Er eroberte Medien, Lydien und Babylon, behandelte die Besiegten aber tolerant. Er fiel um 530 v. Chr. mit etwa 70 in einer Schlacht.", "Er erlaubte den Juden die Rückkehr aus dem babylonischen Exil und den Wiederaufbau ihres Tempels.", "Ein Tonzylinder mit seinen Worten wird manchmal „erste Menschenrechtscharta“ genannt."],
  "Дарий I": ["Ein persischer König, der das riesige Reich ordnete: Er teilte es in Provinzen, führte eine gemeinsame Münze ein und baute die 2700 km lange Königsstraße. Er fiel in Griechenland ein, wurde aber bei Marathon geschlagen. Er starb 486 v. Chr. mit 64.", "Auf der Königsstraße schafften Boten in einer Woche, wofür andere drei Monate liefen.", "Er erbaute eine prächtige neue Stadt, Persepolis."],
  "Сун Дзъ": ["Ein chinesischer Feldherr und Denker, dem das Buch „Die Kunst des Krieges“ zugeschrieben wird. Er diente dem Staat Wu. Über sein Leben weiß man kaum etwas; er soll mit etwa 48 gestorben sein.", "Sein bekanntester Gedanke: Der beste Sieg ist, den Feind ohne Kampf zu besiegen.", "Heute lesen Manager und Sporttrainer sein Buch."],
  "Темистокъл": ["Ein athenischer Politiker und Feldherr. Er überredete Athen, mit dem Silber seiner Minen eine Flotte zu bauen, und schlug damit 480 v. Chr. die Perser bei Salamis. Später wurde er verbannt und starb mit 65 in Persien.", "Die Athener steckten das Geld einer neuen Silberader in Schiffe, statt es unter sich aufzuteilen.", "Am Ende diente er demselben Perserkönig, dessen Vater er besiegt hatte."],
  "Тукидид": ["Ein athenischer Geschichtsschreiber und Feldherr. Er beschrieb den Peloponnesischen Krieg zwischen Athen und Sparta und suchte echte Ursachen statt des Willens der Götter. Er starb um 400 v. Chr. mit etwa 60.", "Die Pest in Athen überlebte er selbst und beschrieb sie genau.", "Das Buch schrieb er in der Verbannung, nachdem er als Befehlshaber eine Stadt nicht retten konnte."],
  "Аристофан": ["Ein athenischer Komödiendichter. In Stücken wie „Die Wolken“, „Die Vögel“ und „Lysistrata“ verspottete er Politiker, Philosophen und den Krieg. Er starb um 386 v. Chr. mit etwa 60.", "In „Lysistrata“ beenden die Frauen einen Krieg, indem sie sich ihren Männern verweigern.", "In „Die Wolken“ verspottet er Sokrates, der in einem Korb in der Luft hängt."],
  "Диоген": ["Ein griechischer Philosoph der Kyniker, der in Armut lebte und jede Sitte missachtete. Er schlief in Athen in einem großen Tonfass und lehrte, dass Glück im einfachen Leben liegt. Er starb mit etwa 89 in Korinth.", "Am helllichten Tag lief er mit einer Laterne herum und sagte, er „suche einen Menschen“.", "Als Alexander der Große fragte, was er wolle, sagte Diogenes: „Geh mir aus der Sonne.“"],
  "Ератостен": ["Ein griechischer Gelehrter und Leiter der Bibliothek von Alexandria. Aus Schatten in zwei Städten berechnete er den Erdumfang und kam dem wahren Wert sehr nahe. Er starb um 194 v. Chr. mit 82.", "Er erfand das „Sieb des Eratosthenes“ zum Finden von Primzahlen.", "Er verwendete als Erster das Wort „Geographie“."],
  "Сципион Африкански": ["Ein römischer Feldherr, der 202 v. Chr. Hannibal bei Zama schlug und den Zweiten Punischen Krieg beendete. Später von politischen Gegnern angeklagt, zog er sich auf sein Landgut zurück und starb dort mit 53.", "Schon mit 25 führte er eine Armee, weit unter dem gesetzlichen Alter.", "Auf seinem Grab soll gestanden haben: „Undankbares Vaterland, du wirst nicht einmal meine Gebeine haben.“"],
  "Помпей Велики": ["Ein römischer Feldherr, der das Mittelmeer von Piraten befreite und den Osten eroberte. Erst Verbündeter, dann Gegner Julius Caesars, verlor er den Bürgerkrieg und floh nach Ägypten, wo er 48 v. Chr. mit 57 getötet wurde.", "Mit den Piraten wurde er in etwa drei Monaten fertig.", "Er baute Roms erstes Steintheater; in dessen Anlage wurde später Caesar ermordet."],
  "Арминий": ["Ein germanischer Cheruskerfürst, der im römischen Heer gedient hatte. Im Jahr 9 lockte er im Teutoburger Wald drei römische Legionen in einen Hinterhalt und vernichtete sie. Er wurde mit etwa 38 von eigenen Verwandten getötet.", "Nach der Niederlage rief Kaiser Augustus: „Varus, gib mir meine Legionen wieder!“", "In Deutschland nennt man ihn Hermann, sein Denkmal ist über 50 Meter hoch."],
  "Сенека": ["Ein römischer Stoiker, Schriftsteller und Lehrer Kaiser Neros. Seine Briefe über Gelassenheit, Zeit und Tod liest man bis heute. Nero beschuldigte ihn einer Verschwörung und befahl ihm, sich zu töten; er starb 65 mit 68.", "Eine Zeit lang war er neben dem jungen Nero der mächtigste Mann Roms.", "Er sagte: „Wir haben nicht zu wenig Zeit, wir verschwenden zu viel davon.“"],
  "Плиний Стари": ["Ein römischer Gelehrter, Schriftsteller und Flottenkommandant. Er schrieb die „Naturgeschichte“, eine riesige Enzyklopädie allen damaligen Wissens. Er starb 79 mit 56 beim Versuch, Menschen beim Ausbruch des Vesuvs zu retten.", "Er arbeitete sogar im Bad und beim Essen, während ihm jemand vorlas.", "Sein Neffe Plinius der Jüngere beschrieb den Ausbruch in einem Brief, die erste genaue Schilderung eines Vulkans."],
  "Будика": ["Königin des britischen Stammes der Icener. Nachdem die Römer ihr Land raubten und ihre Familie demütigten, führte sie im Jahr 60 einen Aufstand und brannte Londinium nieder. Vom römischen Heer besiegt, starb sie mit etwa 31, wohl durch Gift.", "Ihre Aufständischen brannten drei Städte nieder, darunter das spätere London.", "Ihre Bronzestatue mit Streitwagen steht neben dem britischen Parlament."],
  "Цай Лун": ["Ein chinesischer Hofbeamter der Han-Dynastie. Um 105 verbesserte und beschrieb er die Herstellung von Papier aus Rinde, alten Lumpen und Fischernetzen. In Hofintrigen verstrickt, nahm er sich mit etwa 71 das Leben.", "Vor dem Papier schrieben die Chinesen auf Bambusstreifen und teure Seide.", "Das Geheimnis des Papiers erreichte Europa erst etwa tausend Jahre später."],
  "Траян": ["Ein in Spanien geborener römischer Kaiser. Unter ihm war das Reich am größten: Er eroberte Dakien und kam bis zum Persischen Golf. Er baute Märkte, Brücken und Straßen. Er starb 117 mit 63.", "Die Trajanssäule in Rom erzählt den Dakerkrieg in über 2500 Figuren.", "Im heutigen Bulgarien tragen die Städte Nicopolis ad Istrum und Ulpia Oescus seinen Namen."],
  "Адриан": ["Ein römischer Kaiser, der die Eroberungen beendete und die Grenzen sicherte. Er bereiste das ganze Reich und baute den Hadrianswall in Britannien und das Pantheon in Rom. Er starb 138 mit 62.", "Er war der erste Kaiser mit Bart, eine Mode, die ein Jahrhundert hielt.", "Edirne (Adrianopel) wurde von ihm gegründet und trägt seinen Namen."],
  "Гален": ["Ein griechischer Arzt aus Pergamon, der in Rom Leibarzt von Kaisern war. Er erforschte die Anatomie durch Sezieren von Tieren und schrieb Hunderte Werke. Seine Lehren bestimmten die Medizin fast 1400 Jahre. Er starb mit etwa 87.", "Als junger Mann behandelte er verwundete Gladiatoren.", "Er zeigte, dass in den Arterien Blut fließt und nicht Luft, wie man glaubte."],
  "Диоклециан": ["Ein römischer Kaiser, Sohn eines Freigelassenen. Er teilte das Reich unter vier Herrscher, reformierte Steuern und Heer und verfolgte die Christen grausam. 305 trat er zurück und zog in seinem Palast in Split Kohl. Er starb mit etwa 66.", "Er war der einzige römische Kaiser, der freiwillig abdankte.", "Gebeten zurückzukehren, sagte er, wer seinen Kohl sähe, würde ihn nicht darum bitten."],
  "Свети Николай Чудотворец": ["Bischof von Myra in Kleinasien, bekannt für seine Güte. Er half heimlich Armen und schützte Unschuldige. Er starb um 343 mit etwa 73 und wurde einer der beliebtesten Heiligen, Schutzpatron der Seeleute und Fischer.", "Heimlich warf er Goldbeutel ins Haus eines armen Vaters, damit dessen Töchter heiraten konnten; daraus wurde der Nikolaus und Santa Claus.", "In Bulgarien feiert man seinen Tag mit Fisch, meist Karpfen."],
  "Свети Патрик": ["Der Mann, der Irland zum Christentum brachte, geboren im römischen Britannien. Mit 16 wurde er von Piraten entführt und hütete sechs Jahre als Sklave in Irland Schafe, bevor er floh. Er kehrte als Missionar zurück und bekehrte die Iren. Er starb mit etwa 76.", "Die Dreifaltigkeit erklärte er mit einem dreiblättrigen Kleeblatt, das zum Symbol Irlands wurde.", "Sein Tag, der 17. März, wird weltweit in Grün gefeiert."],
  "Теодорих Велики": ["König der Ostgoten, der als Kind Geisel in Konstantinopel war. Er eroberte Italien und regierte es über 30 Jahre friedlich nach römischem Recht. Er starb 526 mit 72 in Ravenna.", "Als junger Mann lebte und kämpfte er auch im heutigen Bulgarien, um Novae bei Swischtow.", "In der deutschen Sage ist er der Held Dietrich von Bern."],
  "Хлодвиг I": ["König der Franken, der Gallien einte und das Frankenreich gründete. Um 500 wurde er Christ und gewann so die Unterstützung der Kirche. Er machte Paris zur Hauptstadt und starb 511 mit 45.", "Aus dem Namen Chlodwig wurde später Ludwig, der Name von 18 französischen Königen.", "Er ließ sich zusammen mit 3000 seiner Krieger taufen."],
  "Свети Бенедикт": ["Ein italienischer Mönch, der das Kloster Montecassino gründete. Er schrieb die „Regel“ für ein Mönchsleben aus Gebet und Arbeit, nach der Tausende Klöster leben. Er starb um 547 mit 67 und ist Schutzpatron Europas.", "Das Motto seiner Mönche lautet „Ora et labora“, „Bete und arbeite“.", "Als junger Mann lebte er drei Jahre allein in einer Höhle."],
  "Императрица Теодора": ["Byzantinische Kaiserin, Gattin Justinians. Von der Schauspielerin und Tochter eines Bärenwärters wurde sie eine der mächtigsten Frauen der Geschichte. Im Nika-Aufstand überredete sie ihren Mann, nicht zu fliehen. Sie starb 548 mit 48.", "Sie sagte, „der Purpur ist ein schönes Leichentuch“: lieber als Kaiser sterben als fliehen.", "Sie setzte Gesetze zum Schutz von Frauen durch."],
  "Хан Кубрат": ["Ein Herrscher aus dem Geschlecht Dulo, der die Bulgaren einte und um 632 Großbulgarien am Schwarzen und Asowschen Meer gründete. Als junger Mann lebte er in Konstantinopel und war ein Freund Kaiser Herakleios’. Er starb um 665 mit etwa 60.", "Der Legende nach gab er seinen Söhnen vor dem Tod ein Bündel Stöcke: Zusammen brechen sie nicht, einzeln ganz leicht.", "Sein Grab wurde wohl bei Pereschtschepyne in der Ukraine gefunden, mit über 20 kg Gold."],
  "Ву Дзътиен": ["Die einzige Frau der chinesischen Geschichte, die in eigenem Namen als Kaiser herrschte. Von der Konkubine wurde sie Gattin des Kaisers und gründete dann selbst eine Dynastie. Sie starb 705 mit 81.", "Sie förderte die Beamtenprüfungen, sodass auch Menschen ohne Adel zur Macht aufsteigen konnten.", "Sie erfand über zehn neue Schriftzeichen, auch eines für ihren eigenen Namen."],
  "Хан Тервел": ["Ein bulgarischer Khan, Sohn Asparuchs. 705 half er dem gestürzten Kaiser Justinian II. zurück auf den Thron und erhielt den Titel „Caesar“ und Land. 717–718 half er Byzanz, die Araber vor Konstantinopel zu schlagen. Er starb um 721 mit etwa 46.", "Er war der erste Ausländer mit dem byzantinischen Titel Caesar.", "Man nennt ihn „Retter Europas“, weil er die Araber vor Konstantinopel aufhielt."],
  "Харун ар-Рашид": ["Abbasidischer Kalif in Bagdad zur Blütezeit des Kalifats. Er förderte Gelehrte, Dichter und Handel, und Bagdad wurde die größte Stadt der Welt. Er starb 809 mit 46.", "Er kommt in „Tausendundeiner Nacht“ vor, wo er verkleidet durch Bagdad streift.", "Karl dem Großen schickte er einen Elefanten namens Abul Abbas und eine kunstvolle Wasseruhr."],
  "Хан Омуртаг": ["Ein bulgarischer Khan, Sohn Krums. Er schloss mit Byzanz einen 30-jährigen Frieden und baute Paläste, Festungen und Brücken. Er hinterließ viele griechische Inschriften. Er starb um 831 mit etwa 41.", "In einer Inschrift steht: „Der Mensch stirbt, auch wenn er gut lebt, und ein anderer wird geboren.“", "Er baute einen neuen Palast an der Donau und eine berühmte Residenz bei Pliska."],
  "Свети Наум Охридски": ["Ein Schüler von Kyrill und Method. Nach Methods Tod kam er nach Bulgarien, wirkte in Pliska und Preslaw, dann in Ohrid. Er gründete ein Kloster am Ufer des Ohridsees und starb dort 910 mit etwa 80.", "Der Legende nach spannte er einen Bären vor den Pflug, nachdem dieser seinen Ochsen gefressen hatte.", "Das Kloster Sveti Naum ist bis heute ein Wallfahrtsort."],
  "Свети Климент Охридски": ["Ein Schüler von Kyrill und Method und einer der größten bulgarischen Schriftgelehrten. In Kutmitschewiza (Ohrid) unterrichtete er über 3500 Schüler und schrieb viele Predigten. Er wurde der erste Bischof, der auf Bulgarisch predigte, und starb 916 mit etwa 76.", "Er soll das Kyrillische geschaffen haben, indem er die Glagoliza vereinfachte und dem griechischen Alphabet annäherte.", "Die Universität Sofia trägt seinen Namen."],
  "Цар Самуил": ["Ein bulgarischer Zar, der das Land jahrzehntelang gegen Kaiser Basileios II. verteidigte, mit Ohrid als Hauptstadt. 1014 wurde sein Heer bei Belasiza geschlagen, und Basileios ließ die Tausenden Gefangenen blenden. Samuil starb bald darauf mit 56 an einem Schlaganfall.", "Jedem Hundertsten ließ man ein Auge, damit er die anderen heimführte.", "Basileios II. bekam den Beinamen „Bulgarentöter“."],
  "Лейф Ериксон": ["Ein isländischer Wikinger, Sohn Eriks des Roten. Um 1000 erreichte er Nordamerika, fast 500 Jahre vor Kolumbus, und nannte es Vinland. Er starb um 1020 mit etwa 50.", "Reste einer Wikingersiedlung wurden in Neufundland, Kanada, gefunden.", "Vinland heißt „Weinland“, denn man fand dort wilde Trauben."],
  "Уилям Завоевателя": ["Herzog der Normandie, der 1066 bei Hastings siegte und König von England wurde. Er baute Burgen wie den Tower of London und ließ das ganze Land im Domesday Book erfassen. Er starb 1087 mit 59.", "Nach ihm füllte sich das Englische mit französischen Wörtern.", "Bei der Beerdigung passte sein Körper nicht ins Grab und platzte."],
  "Фридрих Барбароса": ["Ein deutscher Kaiser aus dem Haus der Staufer, genannt „Rotbart“. Er kämpfte lange in Italien und führte den Dritten Kreuzzug. Er ertrank 1190 mit 68 in einem Fluss in Kleinasien.", "Auf dem Weg ins Heilige Land zog sein Heer auch durch bulgarisches Gebiet, bei Plowdiw.", "Der Sage nach schläft er im Kyffhäuser und erwacht, wenn Deutschland ihn braucht."],
  "Авероес": ["Ein arabischer Philosoph, Arzt und Richter aus Córdoba in Andalusien. Er schrieb ausführliche Kommentare zu Aristoteles, durch die Europa ihn wiederentdeckte. Er fiel in Ungnade, wurde aber begnadigt, und starb 1198 mit 72 in Marrakesch.", "In Europa nannte man ihn einfach „den Kommentator“.", "Raffael malte ihn in der „Schule von Athen“ zwischen die griechischen Philosophen."],
  "Маймонид": ["Ein jüdischer Philosoph, Arzt und Gesetzesgelehrter aus Córdoba. Seine Familie floh vor Verfolgung, und er ließ sich in Kairo nieder, wo er Leibarzt Sultan Saladins wurde. Er starb 1204 mit 66.", "Man sagt: „Von Mose bis Mose gab es keinen wie Mose.“", "Er schrieb auch Bücher über gesunde Ernährung und über Asthma."],
  "Фибоначи": ["Ein italienischer Mathematiker aus Pisa, der in Nordafrika aufwuchs. Mit seinem „Buch der Rechenkunst“ von 1202 brachte er die arabischen Ziffern und die Null nach Europa. Er starb um 1250 mit etwa 80.", "Seine Aufgabe über sich vermehrende Kaninchen ergibt die berühmten Fibonacci-Zahlen: 1, 1, 2, 3, 5, 8 …", "Diese Zahlen findet man in Sonnenblumen, Tannenzapfen und Muscheln."],
  "Цар Калоян": ["Ein bulgarischer Zar, Bruder von Assen und Peter. Er erhielt vom Papst eine Krone und schlug 1205 bei Adrianopel die Ritter des Vierten Kreuzzugs und nahm den lateinischen Kaiser Balduin gefangen. Er wurde 1207 mit 37 bei der Belagerung Thessalonikis getötet.", "Er nannte sich „Rhomäertöter“, eine Antwort auf den Beinamen Basileios’ II.", "Sein Grab wurde wohl in der Kirche der 40 Märtyrer in Weliko Tarnowo gefunden."],
  "Валтер фон дер Фогелвайде": ["Der berühmteste deutsche Minnesänger. Er zog an die Höfe von Fürsten und Kaisern und sang über Liebe, Politik und den Sinn des Lebens. Er starb um 1230 mit etwa 60.", "Außer seinen Liedern ist von ihm nur eine Rechnung erhalten: Ein Bischof bezahlte ihm einen Pelzmantel.", "Der Sage nach verfügte er, dass die Vögel auf seinem Grab täglich mit Körnern gefüttert werden."],
  "Цар Иван Асен II": ["Ein bulgarischer Zar, unter dem das Zweite Bulgarische Reich am größten war und an drei Meere reichte. 1230 besiegte er Theodor Komnenos von Epirus bei Klokotniza, ließ die Gefangenen aber frei. Er starb 1241 mit etwa 51.", "Weil er gefangene Soldaten heimgehen ließ, achteten ihn Volk und Feinde.", "Eine Inschrift in der Kirche der 40 Märtyrer erzählt von seinem Sieg."],
  "Албертус Магнус": ["Ein deutscher Dominikaner, Philosoph und Naturforscher, Lehrer des Thomas von Aquin. Er erforschte Pflanzen, Tiere, Minerale und Chemie und schrieb über fast alles. Er starb 1280 mit etwa 80 in Köln.", "Er beschrieb als Erster reines Arsen.", "Man nannte ihn „Doctor universalis“, weil er über alles Bescheid wusste."],
  "Кублай хан": ["Ein mongolischer Khan, Enkel Dschingis Khans. Er eroberte ganz China, gründete die Yuan-Dynastie und machte Peking zur Hauptstadt. Zweimal versuchte er, in Japan einzufallen, doch Stürme zerschlugen seine Flotte. Er starb 1294 mit 78.", "Marco Polo diente etwa 17 Jahre an seinem Hof.", "Die Japaner nannten die rettenden Stürme „Kamikaze“, „göttlicher Wind“."],
  "Майстер Екхарт": ["Ein deutscher Dominikaner, Theologe und Mystiker. Er predigte auf Deutsch statt auf Latein und lehrte, dass Gott in jeder Seele geboren werden kann. Der Ketzerei angeklagt, starb er um 1328 mit etwa 68, noch vor dem Urteil.", "Er half, das Deutsche auch zur Sprache der Philosophie zu machen.", "Ort und Datum seines Todes sind unbekannt."],
  "Джото": ["Ein italienischer Maler und Architekt aus Florenz. Er malte Menschen mit echten Gefühlen und Tiefe statt der flachen Ikonengesichter, der Beginn der Renaissancekunst. Er entwarf den Glockenturm des Florentiner Doms. Er starb 1337 mit 70.", "Als Junge soll er ein Schaf so gut auf einen Stein gemalt haben, dass ein Maler ihn als Schüler nahm.", "Als Beweis seines Könnens zeichnete er mit einem Zug einen perfekten Kreis."],
  "Манса Муса": ["Herrscher des goldreichen Mali-Reiches in Westafrika, wohl der reichste Mensch der Geschichte. Er baute Moscheen und Schulen in Timbuktu. Er starb um 1337 mit etwa 57.", "Auf dem Weg nach Mekka verteilte er in Kairo so viel Gold, dass dessen Preis jahrelang fiel.", "Eine europäische Karte aus dem 14. Jahrhundert zeigt ihn mit Goldkrone und Goldklumpen in der Hand."],
  "Ибн Батута": ["Ein Marokkaner, der mit 21 zur Pilgerfahrt nach Mekka aufbrach und 24 Jahre später heimkam. Er legte etwa 120 000 km zurück, von Nordafrika bis China, Indien und Ostafrika. Er starb um 1369 mit 65.", "Er reiste dreimal so weit wie Marco Polo.", "In Delhi und auf den Malediven war er Richter."],
  "Франческо Петрарка": ["Ein italienischer Dichter und Gelehrter, der „Vater des Humanismus“. Er schrieb Sonette an Laura, die er in einer Kirche sah und ein Leben lang unerwidert liebte. Er spürte antike Handschriften auf und schrieb sie ab. Er starb 1374 mit 69.", "Er nannte das Mittelalter als Erster „dunkle Zeit“.", "Er bestieg den Mont Ventoux nur wegen der Aussicht, ungewöhnlich für seine Zeit."],
  "Патриарх Евтимий": ["Der letzte Patriarch des Tarnowoer Reiches und ein großer Schriftgelehrter. Er reformierte die Rechtschreibung und berichtigte die Kirchenbücher. 1393 führte er die Verteidigung Tarnowos gegen die Osmanen. Nach dem Fall der Stadt wurde er verbannt und starb um 1402 mit etwa 77.", "Der Überlieferung nach trat er den eindringenden Türken furchtlos entgegen, und sie ließen ihn am Leben.", "Seine Schüler trugen die Tarnowoer Schule bis nach Serbien und Russland."],
  "Тимур": ["Ein turko-mongolischer Eroberer, genannt Tamerlan, „Timur der Lahme“. Er schuf ein riesiges Reich von Indien bis Kleinasien, und seine Hauptstadt Samarkand schmückten prächtige Bauten. Er starb 1405 mit 68 auf dem Weg nach China.", "1402 schlug er den osmanischen Sultan Bayezid I. und nahm ihn gefangen, was den Fall Konstantinopels um 50 Jahre verzögerte.", "Forscher, die 1941 sein Grab öffneten, bestätigten, dass er hinkte."],
  "Джефри Чосър": ["Ein englischer Dichter, der „Vater der englischen Literatur“. Er schrieb die „Canterbury-Erzählungen“, Geschichten von Pilgern unterwegs, und zwar auf Englisch, als man am Hof Französisch sprach. Er starb 1400 mit etwa 57.", "Er arbeitete als Zollbeamter und Diplomat.", "Er war der erste Dichter in der Poets’ Corner der Westminster Abbey."],
  "Цар Иван Шишман": ["Der letzte Zar des Tarnowoer Reiches. Er versuchte, den Osmanen zu widerstehen, doch 1393 fiel Tarnowo. Er starb 1395 mit etwa 45, der Überlieferung nach in Gefangenschaft oder im Kampf bei Nikopol.", "Viele Volkslieder und Legenden erzählen von ihm.", "Viele Orte in Bulgarien tragen seinen Namen, etwa „Schischmans Festung“."],
  "Джън Хъ": ["Ein chinesischer Admiral und Eunuch. Er führte sieben riesige Seereisen nach Indien, Arabien und Ostafrika, mit Schiffen weit größer als die des Kolumbus. Er starb um 1433 mit etwa 62, wohl auf See.", "Seine Flotten hatten bis zu 300 Schiffe und rund 28 000 Mann.", "Er brachte dem Kaiser eine Giraffe aus Afrika."],
  "Ян Хус": ["Ein tschechischer Priester und Professor in Prag, der Reichtum und Sünden der Kirche anprangerte. Mit freiem Geleit zum Konzil von Konstanz gerufen, wurde er verhaftet und 1415 mit 43 verbrannt.", "Sein Tod löste die Hussitenkriege in Böhmen aus.", "Er schrieb und predigte auf Tschechisch und vereinfachte die tschechische Rechtschreibung."],
  "Влад Цепеш": ["Ein walachischer Fürst, der gegen die Osmanen kämpfte, berüchtigt dafür, Feinde pfählen zu lassen. Er fiel 1476 mit 45 im Kampf.", "Der Name „Dracula“ stammt von seinem Vater, einem Mitglied des Drachenordens.", "Der irische Autor Bram Stoker gab seinen Namen dem Vampir Graf Dracula."],
  "Мехмед II Завоевателя": ["Ein osmanischer Sultan, der 1453 mit 21 Konstantinopel eroberte und Byzanz beendete. Er machte die Stadt zur Hauptstadt und baute den Topkapı-Palast. Er starb 1481 mit 49.", "Er ließ seine Schiffe über eingefettete Bretter über Land ziehen, um die Kette vor dem Goldenen Horn zu umgehen.", "Er sprach mehrere Sprachen und ließ sich von einem italienischen Maler porträtieren."],
  "Лукас Кранах Старши": ["Ein deutscher Renaissancemaler und Hofmaler in Sachsen. Er malte Bildnisse, darunter die bekanntesten seines Freundes Martin Luther. Er besaß auch eine Apotheke und eine Druckerei. Er starb 1553 mit 81.", "Er war Trauzeuge bei Luthers Hochzeit.", "Er signierte seine Bilder mit einer geflügelten Schlange."],
  "Парацелз": ["Ein Schweizer Arzt und Alchemist. Er verwarf alte Lehren, schrieb auf Deutsch und setzte chemische Stoffe als Arznei ein. Er zog durch Europa und stritt mit seinen Kollegen. Er starb 1541 mit 47 in Salzburg.", "Er sagte: „Allein die Dosis macht, dass ein Ding kein Gift ist.“", "Er verbrannte öffentlich die Bücher Avicennas, um zu zeigen, dass eine neue Medizin nötig sei."],
  "Ханс Холбайн Младши": ["Ein deutscher Maler aus Augsburg, einer der größten Porträtisten. Er arbeitete in Basel und dann in England als Hofmaler Heinrichs VIII. Er starb 1543 mit 46 in London, wohl an der Pest.", "Sein Bild „Die Gesandten“ zeigt einen verzerrten Schädel, der nur von der Seite richtig aussieht.", "Heinrich VIII. wählte nach seinem Porträt eine Frau und war enttäuscht, als er sie traf."],
  "Карл V": ["Kaiser des Heiligen Römischen Reiches und König von Spanien aus dem Haus Habsburg. Er herrschte über so viele Länder in Europa und Amerika, dass dort „die Sonne nie unterging“. Er kämpfte gegen Frankreich, die Osmanen und die Protestanten. Er dankte ab und starb 1558 mit 58 in einem Kloster.", "Angeblich sprach er Spanisch mit Gott, Italienisch mit Frauen, Französisch mit Männern und Deutsch mit seinem Pferd.", "Auf dem Reichstag zu Worms stand ihm Luther gegenüber."],
  "Готфрид Вилхелм Лайбниц": ["Ein deutscher Philosoph und Mathematiker aus Leipzig, einer der letzten Universalgelehrten. Er erfand die Differentialrechnung unabhängig von Newton und baute eine Rechenmaschine. Er starb 1716 mit 70 in Hannover, fast vergessen.", "Er beschrieb das Binärsystem aus 0 und 1, mit dem heutige Computer rechnen.", "Zu seiner Beerdigung kam nur sein Sekretär."],
  "Мария Сибила Мериан": ["Eine deutsche Künstlerin und Naturforscherin aus Frankfurt. Sie malte Insekten und Pflanzen und zeigte, wie aus einer Raupe ein Schmetterling wird. Mit 52 reiste sie mit ihrer Tochter nach Surinam, um tropische Insekten zu erforschen. Sie starb 1717 mit 69 in Amsterdam.", "Damals glaubten viele, Insekten entstünden aus Schlamm.", "Ihr Bild war auf dem 500-D-Mark-Schein."],
  "Барон Мюнхаузен": ["Ein deutscher Adliger, der als Offizier im russischen Heer gegen die Türken diente. Zurück auf seinem Gut bei Hannover erzählte er Gästen unglaubliche Abenteuer. Er starb 1797 mit 76.", "In den Geschichten reitet er auf einer Kanonenkugel und zieht sich am eigenen Schopf aus dem Sumpf.", "Andere veröffentlichten seine Geschichten ohne seine Zustimmung, was ihn ärgerte."],
  "Готхолд Ефраим Лесинг": ["Ein deutscher Dichter und Dramatiker der Aufklärung. In „Nathan der Weise“ rief er zur Toleranz zwischen Christen, Juden und Muslimen auf. Er war Bibliothekar in Wolfenbüttel. Er starb 1781 mit 52.", "In „Nathan der Weise“ steht die berühmte Ringparabel.", "Er gehörte zu den ersten Deutschen, die vom Schreiben allein leben wollten."],
  "Йозеф Хайдн": ["Ein österreichischer Komponist, der „Vater der Sinfonie und des Streichquartetts“. Fast 30 Jahre war er Hofmusiker der Fürsten Esterházy. Er schrieb über 100 Sinfonien und war Lehrer Beethovens. Er starb 1809 mit 77 in Wien.", "Seine Kaiserhymne ist heute die Melodie der deutschen Nationalhymne.", "In der „Abschiedssinfonie“ löschen die Musiker nacheinander ihre Kerzen und gehen, ein Wink an den Fürsten, dass sie Urlaub wollten."],
  "Софроний Врачански": ["Ein bulgarischer Geistlicher und Schriftsteller, geboren als Stojko Wladislawow in Kotel. Er schrieb Paisijs „Slawobulgarische Geschichte“ ab und wurde Bischof von Wraza. Er verfasste den „Nedelnik“ (1806), das erste gedruckte Buch in neubulgarischer Sprache. Er starb 1813 mit 74 in Bukarest.", "Er schrieb auch „Leben und Leiden des sündigen Sofroni“, die erste bulgarische Autobiografie.", "Er half dem russischen Heer und schrieb Aufrufe an die Bulgaren."],
  "Каролайн Хершел": ["Eine deutsche Astronomin aus Hannover, Schwester Wilhelm Herschels. Sie folgte ihrem Bruder als Sängerin nach England, wurde seine Assistentin und entdeckte selbst acht Kometen. Sie kehrte nach Hannover zurück und starb 1848 mit 97.", "Sie war die erste Frau, der der König ein Gehalt für Forschung zahlte.", "Nach Typhus als Kind blieb sie nur 1,30 m groß."],
  "Георг Вилхелм Фридрих Хегел": ["Ein deutscher Philosoph aus Stuttgart. Er lehrte, dass Geschichte durch Widersprüche voranschreitet und die Welt die Entfaltung des Geistes ist. Er lehrte in Berlin und war der einflussreichste Philosoph seiner Zeit. Er starb 1831 mit 61 an Cholera.", "Seine „Phänomenologie des Geistes“ beendete er, als Napoleon in Jena einzog.", "Mit dem Dichter Hölderlin war er seit dem Studium befreundet."],
  "Фридрих Хьолдерлин": ["Ein schwäbischer Dichter, der begeisterte Verse über das alte Griechenland und die Natur schrieb. Mit etwa 36 erkrankte er psychisch und lebte die letzten 36 Jahre in einem Turm in Tübingen bei einer Schreinerfamilie. Er starb 1843 mit 73.", "Der Hölderlinturm in Tübingen ist heute ein Museum.", "Seine späten Gedichte unterschrieb er mit erfundenen Namen wie „Scardanelli“."],
  "Каспар Давид Фридрих": ["Ein deutscher Maler der Romantik aus Greifswald. Er malte einsame Gestalten vor Nebel, Meer und Bergen. Am Lebensende war er vergessen und arm. Er starb 1840 mit 65 in Dresden.", "Sein bekanntestes Bild ist „Der Wanderer über dem Nebelmeer“.", "Als Junge ertrank sein Bruder, als er ihn beim Schlittschuhlaufen rettete."],
  "Карл Дрез": ["Ein deutscher Erfinder aus Karlsruhe. 1817 baute er die „Laufmaschine“, ein hölzernes Zweirad ohne Pedale, den Vorläufer des Fahrrads. Er erfand auch eine Schreibmaschine. Er starb 1851 mit 66 in Armut.", "Er erfand sie, nachdem das „Jahr ohne Sommer“ viele Pferde getötet hatte und man Verkehr ohne sie brauchte.", "Er erfand auch eine Maschine, die Klaviermusik mitschreibt."],
  "Вилхелм Грим": ["Ein deutscher Sprachforscher und Märchensammler, der jüngere der Brüder Grimm. Mit seinem Bruder Jacob sammelte er die „Kinder- und Hausmärchen“: „Schneewittchen“, „Aschenputtel“, „Hänsel und Gretel“. Sie begannen auch das große Deutsche Wörterbuch. Er starb 1859 mit 73 in Berlin.", "Wilhelm erzählte die Märchen sanfter und schöner für Kinder nach.", "Das von den Brüdern begonnene Wörterbuch wurde erst 1961 fertig."],
  "Артур Шопенхауер": ["Ein deutscher Philosoph aus Danzig, bekannt für seinen Pessimismus. Er lehrte, die Welt werde von einem blinden Willen getrieben und das Leben sei Leid, gelindert durch Kunst und Mitleid. Anerkennung kam erst im Alter. Er starb 1860 mit 72 in Frankfurt.", "Er legte seine Vorlesungen bewusst auf Hegels Zeit, und zu ihm kam fast niemand.", "Er lebte mit mehreren Pudeln, die alle Atma hießen."],
  "Васил Априлов": ["Ein bulgarischer Kaufmann und Wohltäter aus Gabrowo, der in Odessa lebte. 1835 gründete er mit Nikola Palausow in Gabrowo die erste weltliche bulgarische Schule. Er starb 1847 mit 58 in Galați.", "Als junger Mann hielt er sich für einen Griechen; ein Buch Juri Wenelins brachte ihn zu seinen bulgarischen Wurzeln zurück.", "Das Aprilow-Gymnasium in Gabrowo trägt seinen Namen."],
  "Неофит Рилски": ["Ein bulgarischer Mönch, Lehrer und Gelehrter aus Bansko, der „Patriarch der bulgarischen Pädagogik“. Er schrieb die erste bulgarische Grammatik (1835) und war der erste Lehrer der Aprilow-Schule in Gabrowo. Seine letzten Jahre verbrachte er im Rilakloster, wo er 1881 mit 88 starb.", "30 Jahre arbeitete er an einem großen Wörterbuch des Bulgarischen.", "Er übersetzte das Neue Testament ins gesprochene Bulgarisch."],
  "Хайнрих Хайне": ["Ein deutscher Dichter jüdischer Herkunft aus Düsseldorf. Er schrieb zarte Liebesgedichte und scharfe Satiren. Wegen der Zensur lebte er in Paris, wo er die letzten acht Jahre bettlägerig war. Er starb 1856 mit 58.", "Sein Gedicht „Die Lorelei“ wurde zum Volkslied.", "Er schrieb vorausahnend: „Dort, wo man Bücher verbrennt, verbrennt man auch am Ende Menschen.“"],
  "Петър Берон": ["Ein bulgarischer Gelehrter und Aufklärer aus Kotel. 1824 gab er die „Fibel mit verschiedenen Belehrungen“ heraus, die „Fischfibel“, das erste weltliche bulgarische Schulbuch. Später wurde er Arzt und schrieb über Physik und Philosophie. Er wurde 1871 mit 72 in Craiova ermordet.", "„Fischfibel“ heißt sie wegen des Delfins auf der letzten Seite.", "Sein Vermögen vermachte er bulgarischen Schulen."],
  "Кольо Фичето": ["Ein autodidaktischer bulgarischer Baumeister der Wiedergeburt aus Drjanowo. Er baute Brücken, Kirchen und Gebäude: die Brücke von Bjala, die überdachte Brücke in Lowetsch, den Konak in Tarnowo. Er starb 1881 mit 81.", "Der Beiname „Fitscheto“ heißt „der Kleine“, er war klein gewachsen.", "Seine Brücke in Bjala ist 276 Meter lang."],
  "Захари Зограф": ["Ein bulgarischer Ikonenmaler der Wiedergeburt aus Samokow. Er malte Fresken im Rila-, Batschkowo- und Trojan-Kloster. Er malte auch einfache Menschen und sich selbst, was neu war. Er starb 1853 mit 43 an Typhus.", "Er malte das erste bulgarische Selbstbildnis.", "Im Kloster Trojan malte er das Jüngste Gericht mit Menschen in der Kleidung seiner Zeit."],
  "Роберт Шуман": ["Ein deutscher Komponist der Romantik aus Zwickau. Er wollte Pianist werden, verletzte sich aber die Hand und widmete sich dem Komponieren. Er heiratete die Pianistin Clara Wieck. Schwer depressiv stürzte er sich in den Rhein und starb 1856 mit 46 in einer Heilanstalt.", "In einem einzigen Jahr, dem Jahr seiner Hochzeit, schrieb er über hundert Lieder.", "Er entdeckte und förderte den jungen Brahms."],
  "Баба Тонка": ["Tonka Obretenowa aus Russe, die „Mutter der Revolutionäre“. Ihr Haus war geheimes Quartier der Komitees, wo Aufständische und Waffen versteckt wurden. Ihre Söhne kämpften mit, zwei von ihnen starben. Sie starb 1893 mit 81.", "Unter ihrer Kleidung trug sie Waffen und Briefe an den türkischen Wachen vorbei.", "Auch ihre Tochter Petrana war Revolutionärin."],
  "Вернер фон Сименс": ["Ein deutscher Erfinder und Unternehmer. Er gründete die Firma Siemens, baute Telegrafenlinien über ganze Kontinente und fand heraus, wie man starke Generatoren baut. Er starb 1892 mit 75.", "Er baute die erste elektrische Straßenbahn und den ersten elektrischen Aufzug.", "Die Einheit des elektrischen Leitwerts heißt „Siemens“."],
  "Евлоги Георгиев": ["Ein bulgarischer Kaufmann und Bankier aus Karlowo, der mit seinem Bruder Christo Georgiew in Bukarest lebte. Er stiftete eine riesige Summe und Land für die Gründung der Universität Sofia. Er starb 1897 mit 78 in Bukarest.", "Das Hauptgebäude der Universität steht auf dem von den Brüdern geschenkten Grund, mit ihren Statuen an der Fassade.", "Er gab den Revolutionären Geld, war aber gegen einen bewaffneten Aufstand."],
  "Клара Шуман": ["Eine deutsche Pianistin und Komponistin aus Leipzig, ein Wunderkind. Sie heiratete Robert Schumann gegen den Willen ihres Vaters, bekam acht Kinder und gab weiter Konzerte in ganz Europa. Sie starb 1896 mit 76.", "Mit Brahms war sie ein Leben lang eng befreundet.", "Ihr Bild war auf dem 100-D-Mark-Schein."],
  "Теодор Фонтане": ["Ein deutscher Schriftsteller aus Neuruppin, gelernter Apotheker. Er war Journalist und Kriegsberichterstatter und schrieb über seine Wanderungen durch die Mark Brandenburg. Seine besten Romane wie „Effi Briest“ schrieb er nach 60. Er starb 1898 mit 78 in Berlin.", "1870 wurde er als Berichterstatter von den Franzosen als Spion verhaftet.", "Seine Ballade vom Herrn von Ribbeck und den Birnen lernt man in der Schule."],
  "Добри Чинтулов": ["Ein bulgarischer Dichter und Lehrer aus Sliwen. Er schrieb aufrührerische Verse, die zu Liedern des ganzen Volkes wurden. Er unterrichtete in Sliwen und starb dort 1886 mit 64.", "Sein Lied „Steh auf, steh auf, Balkanheld“ sangen die Revolutionäre.", "Seine Gedichte verbreiteten sich mündlich, ohne gedruckt zu sein."],
  "Хайнрих Шлиман": ["Ein deutscher Kaufmann und Archäologe. Reich geworden durch Handel und Goldrausch, suchte er Troja nach Homers Versen und fand es in der Türkei. Er grub auch in Mykene. Er starb 1890 mit 68 in Neapel.", "Er schmuggelte den „Schatz des Priamos“ außer Landes und schmückte seine Frau damit.", "Er sprach über zehn Sprachen und lernte jede in wenigen Wochen."],
  "Найден Геров": ["Ein bulgarischer Lehrer und Sprachforscher der Wiedergeburt aus Kopriwschtiza. Er schuf das „Wörterbuch der bulgarischen Sprache“ mit über 70 000 Wörtern. Viele Jahre war er russischer Konsul in Plowdiw. Er starb 1900 mit 77.", "Schon als Schüler schrieb er das erste bulgarische Versepos.", "Als Konsul half er vielen Bulgaren, der Verfolgung zu entkommen."],
  "Йохан Щраус (син)": ["Ein österreichischer Komponist, der „Walzerkönig“. Er schrieb über 500 Walzer, Polkas und Operetten, darunter „An der schönen blauen Donau“ und „Die Fledermaus“. Mit seinem Orchester reiste er durch Europa und Amerika. Er starb 1899 mit 73 in Wien.", "Sein Vater, selbst Komponist, wollte nicht, dass der Sohn Musiker wird.", "„An der schönen blauen Donau“ erklingt in Wien jedes Neujahr."],
  "Петко Славейков": ["Ein bulgarischer Dichter, Journalist und Politiker aus Tarnowo. Er gab Zeitungen heraus, sammelte Tausende Volkslieder und Sprichwörter und kämpfte für eine eigene bulgarische Kirche. Nach der Befreiung war er Minister. Er starb 1895 mit 67.", "Er war der Vater des Dichters Pentscho Slawejkow.", "Er gab die Zeitungen „Gajda“ und „Makedonija“ heraus."],
  "Йохана Шпири": ["Eine Schweizer Schriftstellerin aus einem Dorf bei Zürich. Sie schrieb „Heidi“, die Geschichte eines Mädchens, das beim Großvater in den Alpen lebt. Sie starb 1901 mit 74 in Zürich.", "„Heidi“ wurde in etwa 50 Sprachen übersetzt.", "Ihr erstes Buch erschien ohne ihren Namen, nur mit Initialen."],
  "Панайот Хитов": ["Ein bulgarischer Heiducke und Anführer aus Sliwen. Er führte Freischaren im Balkangebirge, 1867 eine mit Wassil Lewski als Fahnenträger. Er erlebte die Befreiung und starb 1918 mit 87 in Russe.", "Er schrieb Erinnerungen: „Wie ich Heiducke wurde“.", "Lewski war sein Fahnenträger."],
  "Филип Тотю": ["Ein bulgarischer Heiducke und Anführer aus dem Dorf Gartschi (heute Wischowgrad). 1867 führte er mit Panajot Hitow eine Freischar aus Rumänien ins Balkangebirge. Er erlebte die Befreiung und starb 1907 mit 77.", "Über ihn singt man Volkslieder.", "Er war einer der wenigen Anführer, die die Befreiung erlebten."],
  "Франц Йосиф I": ["Kaiser von Österreich und König von Ungarn, der 68 Jahre regierte, von 1848 bis 1916. Er erlebte verlorene Kriege, den Tod seines Sohnes und die Ermordung seiner Frau Sisi. Nach dem Attentat auf den Thronfolger erklärte er Serbien den Krieg, der Beginn des Ersten Weltkriegs. Er starb 1916 mit 86.", "Er wurde mit 18 Kaiser.", "Er schlief auf einem eisernen Feldbett und stand täglich um 4 Uhr auf."],
  "Николаус Ото": ["Ein deutscher Erfinder und Autodidakt. 1876 schuf er den Viertakt-Verbrennungsmotor, der die meisten Autos antreibt. Er starb 1891 mit 58 in Köln.", "Vorher war er Handlungsreisender für Zucker und Kolonialwaren.", "Der Viertaktprozess heißt bis heute „Otto-Prozess“."],
  "Вилхелм Буш": ["Ein deutscher Dichter und Zeichner, ein Vater des Comics. Er schuf „Max und Moritz“, eine Bildergeschichte in Reimen über zwei Lausbuben. Er lebte zurückgezogen auf dem Land und starb 1908 mit 75.", "Die Rechte an „Max und Moritz“ verkaufte er für wenig Geld, und der Verleger wurde reich.", "Als Kind lebte er bei seinem Onkel, einem Pfarrer, und sah drei Jahre seine Eltern nicht."],
  "Йоханес Брамс": ["Ein deutscher Komponist aus Hamburg. Als Junge spielte er in Hafenkneipen Klavier. Später ließ er sich in Wien nieder und schrieb Sinfonien, Konzerte und „Ungarische Tänze“. Er starb 1897 mit 63.", "Brahms’ „Wiegenlied“ ist eine der bekanntesten Melodien der Welt.", "An seiner ersten Sinfonie arbeitete er 21 Jahre, aus Furcht vor Beethovens Schatten."],
  "Любен Каравелов": ["Ein bulgarischer Schriftsteller, Journalist und Revolutionär aus Kopriwschtiza. In Bukarest gab er Zeitungen heraus und war erster Vorsitzender des Bulgarischen Revolutionären Zentralkomitees. Er starb 1879 mit 44 in Russe an Tuberkulose, kurz nach der Befreiung.", "Er schrieb die Erzählung „Bulgaren aus alter Zeit“.", "Im Krieg verlor er bei einem Brand in Russe seine Bibliothek und seine Papiere."],
  "Готлиб Даймлер": ["Ein deutscher Ingenieur und Erfinder aus Schorndorf. Mit Wilhelm Maybach baute er einen leichten, schnellen Benzinmotor, das erste Motorrad und eines der ersten Autos. Aus seiner Firma ging später Mercedes-Benz hervor. Er starb 1900 mit 65.", "Das erste Motorrad war aus Holz und hieß „Reitwagen“.", "Der Mercedes-Stern steht für Motoren zu Land, zu Wasser und in der Luft."],
  "Императрица Сиси": ["Elisabeth in Bayern, Gattin Kaiser Franz Josephs. Berühmt für ihre Schönheit und ihr langes Haar, hasste sie das Hofleben und reiste ständig. Sie liebte Ungarn und trug zum Ausgleich mit Österreich-Ungarn bei. 1898 erstach sie ein Anarchist in Genf mit einer Feile, sie war 60.", "Ihr Haar reichte bis zu den Fersen, das Waschen dauerte einen ganzen Tag.", "Der Stich war so fein, dass sie weiterging, ohne zu merken, dass sie verletzt war."],
  "Фердинанд фон Цепелин": ["Ein deutscher Graf und General aus Konstanz. Nach seiner Pensionierung mit 52 baute er riesige Starrluftschiffe. Sein erster Zeppelin flog 1900 über dem Bodensee. Er starb 1917 mit 78.", "Als Beobachter im Amerikanischen Bürgerkrieg stieg er zum ersten Mal in einen Ballon.", "Zeppeline brachten Passagiere über den Atlantik, Jahre bevor es Flugzeuge taten."],
  "Хаджи Димитър": ["Ein bulgarischer Heiducke und Revolutionär aus Sliwen. 1868 überquerte er mit Stefan Karadscha und 127 Mann die Donau. Nach harten Kämpfen fiel er mit 28 auf dem Busludscha.", "Botew machte ihn im Gedicht „Hadschi Dimitar“ unsterblich: „Wer im Kampf für die Freiheit fällt, der stirbt nicht …“", "Sein Haus in Sliwen ist heute ein Museum."],
  "Карл Май": ["Ein deutscher Schriftsteller aus Sachsen, Autor von Abenteuern im Wilden Westen und im Orient, mit den Helden Winnetou und Old Shatterhand. Als junger Mann saß er wegen Betrugs im Gefängnis. Er starb 1912 mit 70.", "Er schrieb über Amerika, ohne dort gewesen zu sein; er besuchte es erst im Alter.", "Seine Bücher wurden über 200 Millionen Mal verkauft."],
  "Георги Бенковски": ["Ein bulgarischer Revolutionär aus Kopriwschtiza, geboren als Gawril Chlatew. Er führte im Aprilaufstand 1876 den Revolutionsbezirk Panagjurischte und die „Fliegende Schar“. Er fiel mit 33 in einem Hinterhalt bei Tetewen.", "Er ließ sich eine Uniform nähen und ritt von Dorf zu Dorf, um das Volk zu erheben.", "Den Namen „Benkowski“ übernahm er von einem Polen, den er in Kleinasien traf."],
  "Капитан Петко войвода": ["Ein bulgarischer Heiducke und Revolutionär aus Doganhisar (heute Aisymi, Griechenland). Jahrzehntelang kämpfte er gegen die Osmanen in den Rhodopen und an der Ägäis. Nach der Befreiung lebte er in Warna und starb 1900 mit 55.", "Er kämpfte in Italien mit Garibaldi.", "Über ihn wurde die beliebte Fernsehserie „Kapitän Petko Wojwoda“ gedreht."],
  "Лудвиг II Баварски": ["König von Bayern, der „Märchenkönig“. Statt Politik widmete er sich Wagners Musik und baute Märchenschlösser wie Neuschwanstein. Er wurde für verrückt erklärt und abgesetzt und einen Tag später mit 40 tot im Starnberger See gefunden.", "Neuschwanstein inspirierte das Dornröschenschloss von Disney.", "Sein Tod ist bis heute ein Rätsel."],
  "Ото Лилиентал": ["Ein deutscher Ingenieur, der „Segelflugkönig“. Er studierte den Flug der Störche und machte über 2000 Flüge mit selbst gebauten Gleitern. Bei einem Absturz 1896 brach er sich das Rückgrat und starb mit 48.", "Seine letzten Worte sollen gewesen sein: „Opfer müssen gebracht werden.“", "Die Brüder Wright studierten seine Flüge."],
  "Захари Стоянов": ["Ein bulgarischer Revolutionär und Schriftsteller aus Medwen, einst Hirte. Er nahm am Aprilaufstand teil und beschrieb ihn in den „Aufzeichnungen über die bulgarischen Aufstände“. Er führte 1885 die Vereinigung an und war Parlamentspräsident. Er starb 1889 mit 39 in Paris.", "Er schrieb Biografien von Lewski, Botew und Benkowski.", "Er begann als Hirtenjunge und brachte sich alles selbst bei."],
  "Тодор Каблешков": ["Ein bulgarischer Revolutionär aus Kopriwschtiza. Am 20. April 1876 schrieb er den „blutigen Brief“, der den Aprilaufstand ausrief. Nach der Niederlage gefasst, erschoss er sich mit 25 in Gefangenschaft in Gabrowo.", "„Blutig“ heißt der Brief der Überlieferung nach, weil er mit dem Blut eines getöteten Polizisten gezeichnet war.", "Er sprach mehrere Sprachen und studierte in Konstantinopel."],
  "Стефан Стамболов": ["Ein bulgarischer Revolutionär und Staatsmann aus Tarnowo. Nach der Befreiung war er Parlamentspräsident und Regent, dann Ministerpräsident. Er regierte hart, modernisierte aber das Land. Er wurde in Sofia mit Messern angegriffen und starb 1895 mit 41.", "Man nannte ihn den „bulgarischen Bismarck“.", "Als junger Mann schrieb er Gedichte und war mit Botew befreundet."],
  "Райна Княгиня": ["Rajna Popgeorgiewa, eine Lehrerin aus Panagjurischte. Sie nähte die Fahne des Aprilaufstands mit der Inschrift „Freiheit oder Tod“. Nach dem Aufstand wurde sie eingesperrt und gefoltert. Später wurde sie Hebamme und starb 1917 mit 61.", "Den Beinamen „Knjaginja“, „Fürstin“, gab ihr Benkowski."],
  "Княз Александър Батенберг": ["Ein deutscher Prinz, 1879 mit 22 zum ersten Fürsten des freien Bulgarien gewählt. Er unterstützte die Vereinigung und führte das Heer 1885 zum Sieg bei Sliwniza. Durch einen Putsch gestürzt, starb er 1893 mit 36 in Graz.", "Auf eigenen Wunsch ist er in Sofia begraben, sein Mausoleum steht im Stadtzentrum.", "Er war heimlich mit einer Enkelin Königin Victorias verlobt, doch die Ehe kam nicht zustande."],
  "Хайнрих Херц": ["Ein deutscher Physiker aus Hamburg. 1887 wies er als Erster elektromagnetische Wellen nach, die Grundlage von Radio, Fernsehen und Mobilfunk. Er starb 1894 mit 36.", "Er sagte, seine Entdeckung habe „keinerlei praktischen Nutzen“.", "Die Einheit der Frequenz heißt „Hertz“."],
  "Рудолф Дизел": ["Ein deutscher Ingenieur, in Paris geboren. Er erfand den Motor, der den Kraftstoff allein durch Verdichten der Luft zündet, den Dieselmotor. 1913 verschwand er von einem Schiff im Ärmelkanal und wurde mit 55 tot aufgefunden.", "Einer seiner Motoren lief auf der Pariser Weltausstellung mit Erdnussöl.", "Sein Tod ist bis heute ein Rätsel: Unfall, Selbstmord oder Mord."],
  "Густав Малер": ["Ein österreichischer Komponist und Dirigent aus Böhmen. Er leitete die Wiener Hofoper und schrieb gewaltige Sinfonien voll Natur, Tod und Hoffnung. Er starb 1911 mit 50 in Wien.", "Er sagte: „Die Sinfonie muss sein wie die Welt. Sie muss alles umfassen.“", "Er fürchtete eine neunte Sinfonie, denn Beethoven und andere starben nach ihrer neunten."],
  "Цар Фердинанд": ["Ein deutscher Prinz aus dem Haus Sachsen-Coburg und Gotha, 1887 zum Fürsten Bulgariens gewählt. 1908 erklärte er die Unabhängigkeit und wurde Zar. Er führte das Land in die Balkankriege und den Ersten Weltkrieg. 1918 dankte er ab und starb 1948 mit 87 in Coburg.", "Als leidenschaftlicher Botaniker und Insektenkundler gründete er Gärten und Museen.", "Er fuhr gern selbst Lokomotive."],
  "Петър Дънов": ["Ein bulgarischer spiritueller Lehrer, genannt Meister Beinsa Duno. Er gründete die Weiße Bruderschaft und lehrte Liebe, Weisheit und Wahrheit. Seine Anhänger tanzen Paneurhythmie und begrüßen in den Rila-Bergen den Sonnenaufgang. Er starb 1944 mit 80 in Sofia.", "Jeden Sommer führte er seine Anhänger zu den Sieben Rila-Seen.", "Er schrieb auch die Musik zur Paneurhythmie."],
  "Пенчо Славейков": ["Ein bulgarischer Dichter aus Trjawna, Sohn Petko Slawejkows. Er studierte in Leipzig und wollte die bulgarische Dichtung auf europäisches Niveau heben. Er schrieb das Epos „Blutiges Lied“. Für den Nobelpreis nominiert, starb er 1912 mit 46 in Italien.", "Als Junge geriet er in eiskaltes Wasser und hatte danach lebenslang Mühe beim Gehen und Sprechen.", "In der Anthologie „Auf der Insel der Seligen“ stellte er erfundene Dichter vor, deren Verse von ihm selbst waren."],
  "Гоце Делчев": ["Ein bulgarischer Revolutionär und Lehrer aus Kukusch. Ein Anführer der Inneren Makedonisch-Adrianopler Revolutionären Organisation, die für die Befreiung Makedoniens und Thrakiens kämpfte. Er fiel 1903 mit 31 in einem Gefecht beim Dorf Banitsa.", "Er sagte: „Ich verstehe die Welt allein als ein Feld für den kulturellen Wettstreit der Völker.“", "Er besuchte die Militärschule in Sofia, wurde aber ausgeschlossen."],
  "Яне Сандански": ["Ein bulgarischer Revolutionär aus Wlachi, genannt „Zar des Pirin“. Als Anführer der Revolutionsorganisation führte er Freischaren im Pirin. Er organisierte die Entführung der amerikanischen Missionarin Miss Stone gegen Lösegeld. Er wurde 1915 mit 42 bei Roschen in einem Hinterhalt getötet.", "Das Lösegeld für Miss Stone betrug 14 000 türkische Pfund, gesammelt in Amerika.", "Die Stadt Sandanski trägt seinen Namen."],
  "Фердинанд Порше": ["Ein österreichischer Autokonstrukteur aus Böhmen. Schon 1900 baute er eines der ersten Hybridautos, in den 1930ern konstruierte er den VW Käfer. Er gründete die Firma Porsche und starb 1951 mit 75.", "Der Käfer wurde über 21 Millionen Mal gebaut.", "Er hat nie ein Studium abgeschlossen, bekam aber einen Ehrendoktor."],
  "Райнер Мария Рилке": ["Ein österreichischer Dichter, in Prag geboren. Er schrieb die „Duineser Elegien“ und die „Sonette an Orpheus“, und seine „Briefe an einen jungen Dichter“ liest man bis heute. Er starb 1926 mit 51 in der Schweiz an Leukämie.", "Als kleinen Jungen zog ihn seine Mutter wie ein Mädchen an.", "In Paris war er Sekretär des Bildhauers Rodin."],
  "Конрад Аденауер": ["Ein deutscher Politiker und Oberbürgermeister von Köln, den die Nazis absetzten. Nach dem Krieg wurde er mit 73 erster Bundeskanzler und führte die Bundesrepublik 14 Jahre zu Demokratie, Wirtschaftswunder und Aussöhnung mit Frankreich. Er starb 1967 mit 91.", "Er wurde mit einer Stimme Mehrheit gewählt, seiner eigenen.", "Er ließ eine Sojawurst und ein Gerät gegen Insekten patentieren."],
  "Херман Хесе": ["Ein deutscher Schriftsteller aus dem Schwarzwald, später Schweizer. In Romanen wie „Der Steppenwolf“, „Siddhartha“ und „Das Glasperlenspiel“ ging es um den Weg zu sich selbst. 1946 erhielt er den Nobelpreis, er starb 1962 mit 85.", "Als Junge floh er aus dem Klosterseminar.", "In den 1960ern wurde er ein Liebling der Hippies."],
  "Стамен Григоров": ["Ein bulgarischer Arzt und Mikrobiologe aus dem Dorf Studen Iswor. 1905 entdeckte er in Genf das Bakterium, das bulgarischen Joghurt macht: Lactobacillus bulgaricus. Später entwickelte er auch einen Tuberkulose-Impfstoff. Er starb 1945 mit 67.", "Er fand es mit 27, noch als Student.", "In Studen Iswor gibt es ein Joghurtmuseum."],
  "Лизе Майтнер": ["Eine österreichische Physikerin aus Wien. 30 Jahre arbeitete sie in Berlin mit Otto Hahn. Als Jüdin floh sie vor den Nazis nach Schweden und erklärte von dort die Kernspaltung. Die Arbeit an der Atombombe lehnte sie ab. Sie starb 1968 mit 89 in England.", "Den Nobelpreis für die Spaltung bekam nur Hahn, sie ging leer aus.", "Das Element Meitnerium ist nach ihr benannt."],
  "Александър Стамболийски": ["Ein bulgarischer Politiker aus Slawowiza, Führer des Bauernbundes. Als Kriegsgegner wurde er eingesperrt, nach dem Krieg wurde er Ministerpräsident. Er führte eine Bodenreform und einen Arbeitsdienst ein. Durch einen Putsch gestürzt, wurde er 1923 mit 44 grausam ermordet.", "Seine Mörder schlugen ihm die Hand ab, mit der er den Vertrag mit Jugoslawien unterschrieben hatte."],
  "Ото Хан": ["Ein deutscher Chemiker aus Frankfurt, der „Vater der Kernchemie“. 1938 entdeckte er mit Fritz Straßmann die Spaltung des Urankerns. Er erhielt den Nobelpreis für Chemie. Nach dem Krieg kämpfte er gegen Atomwaffen. Er starb 1968 mit 89.", "Als er von Hiroshima hörte, war er so erschüttert, dass seine Kollegen um ihn fürchteten.", "Von seinem Nobelpreis erfuhr er in britischer Internierung."],
  "Йордан Йовков": ["Ein bulgarischer Schriftsteller aus Scherawna, ein Meister der Erzählung. Lehrer in der Dobrudscha, dann Diplomat in Bukarest. Er schrieb „Legenden aus dem Balkan“, „Letzte Freude“ und „Das Gut an der Grenze“. Er starb 1937 mit 56 in Plowdiw.", "Seine Erzählung „Das Lied der Räder“ liest man in der Schule.", "Er kämpfte als Offizier in den Balkankriegen und im Ersten Weltkrieg."],
  "Алфред Вегенер": ["Ein deutscher Meteorologe und Polarforscher aus Berlin. Er vermutete, dass die Kontinente einst einer waren, Pangaea, und langsam auseinanderdriften. Zu Lebzeiten glaubte ihm keiner. Er starb 1930 mit 50 auf einer Expedition in Grönland.", "Er sah, dass die Küste Südamerikas wie ein Puzzleteil zu Afrika passt.", "Er stellte einen Weltrekord im Ballonfahren auf: über 52 Stunden."],
  "Стефан Цвайг": ["Ein österreichischer Schriftsteller aus Wien, in den 1930ern einer der meistgelesenen der Welt. Er schrieb Novellen, Biografien und die Erinnerungen „Die Welt von Gestern“. Als Jude floh er vor den Nazis nach England und dann nach Brasilien, wo er sich 1942 mit 60 das Leben nahm.", "Seine letzte Novelle ist die „Schachnovelle“.", "Die Nazis verbrannten seine Bücher."],
  "Владимир Димитров – Майстора": ["Ein bulgarischer Maler aus Frolosch bei Kjustendil. Er malte Bauern, Mädchen und Früchte in leuchtenden, märchenhaften Farben. Er lebte bescheiden im Dorf Schischkowzi. Er starb 1960 mit 78.", "Seine Bilder verschenkte er an die Bauern, die ihn verpflegten.", "Schon als junger Mann nannte man ihn „den Meister“."],
  "Асен Златаров": ["Ein bulgarischer Chemiker, Arzt und engagierter Bürger aus Haskowo. Er erforschte die Chemie der Lebensmittel und schrieb populärwissenschaftliche Bücher. Er organisierte kostenlose Vorträge und Hilfe für Arme. Er starb 1936 mit 51.", "Er schrieb auch Gedichte.", "Die Universität in Burgas trägt seinen Namen."],
  "Ран Босилек": ["Gentscho Negenzow, ein bulgarischer Kinderbuchautor aus Gabrowo. Er schrieb „Patilanzi“ und „Ungeborenes Mädchen“ und erzählte Märchen nach. Er starb 1958 mit 71.", "Sein Deckname bedeutet „früher Basilikum“.", "Die Helden der „Patilanzi“, Rischko, Gogo und Satschko, kennt jedes bulgarische Kind."],
  "Дора Габе": ["Eine bulgarische Dichterin aus Dabowik bei Dobritsch. Sie schrieb Gedichte für Kinder und Erwachsene und übersetzte aus vielen Sprachen. Sie lebte fast ein Jahrhundert und starb 1983 mit 97.", "Sie studierte in Genf und Grenoble und sprach mehrere Sprachen.", "Generationen von Kindern können ihre Gedichte auswendig."],
  "Димчо Дебелянов": ["Ein bulgarischer Dichter aus Kopriwschtiza. Er schrieb zarte, traurige Verse wie „Ins Vaterhaus zurückkehren“. Er meldete sich im Ersten Weltkrieg freiwillig und fiel 1916 mit 29 bei Gorno Karadschowo.", "Sein Gedicht „Ich will dich immer so in Erinnerung behalten“ gehört zu den beliebtesten in Bulgarien.", "Die Statue auf seinem Grab in Kopriwschtiza, eine Mutter, die auf ihren Sohn wartet, kennt das ganze Land."],
  "Ервин Шрьодингер": ["Ein österreichischer Physiker aus Wien, einer der Begründer der Quantenmechanik. Seine Gleichung beschreibt das Verhalten von Elektronen. 1933 erhielt er den Nobelpreis, er starb 1961 mit 73 in Wien.", "Er erdachte das Gedankenexperiment mit der Katze, die zugleich tot und lebendig ist, bis man die Kiste öffnet.", "Sein Bild war auf dem österreichischen 1000-Schilling-Schein."],
  "Чудомир": ["Dimitar Tschorbadschijski, ein bulgarischer Humorist und Maler aus Turija. Als Lehrer in Kasanlak schrieb er lustige, warme Geschichten über das Dorfleben. Er starb 1967 mit 76.", "Er zeichnete einfach mit „Tschudomir“.", "Sein Haus in Kasanlak ist ein Museum, in dem ein Fest des Humors stattfindet."],
  "Дан Колов": ["Ein bulgarischer Ringer aus Sennik bei Sewliewo, Weltmeister im Freistil. Mit 17 ging er nach Amerika, arbeitete als Holzfäller und Bergmann und wurde dann ein Star im Ring. Von über 1500 Kämpfen verlor er nur wenige. Er starb 1940 mit 47 in seinem Heimatdorf.", "Er sagte: „Ein Bulgare kann nicht besiegt werden!“", "Er soll zwei Autos festgehalten haben, die in entgegengesetzte Richtungen zogen."],
  "Цар Борис III": ["Zar von Bulgarien von 1918 bis 1943, Sohn Ferdinands. Er regierte in schweren Jahren und war im Zweiten Weltkrieg mit Deutschland verbündet, schickte aber keine Truppen an die Ostfront. Er starb 1943 mit 49 plötzlich nach einem Treffen mit Hitler.", "Wie sein Vater liebte er Züge und fuhr selbst Lokomotive.", "Während seiner Herrschaft wurden die Juden im bulgarischen Kernland vor der Deportation bewahrt."],
  "Димитър Пешев": ["Ein bulgarischer Politiker aus Kjustendil, Vizepräsident des Parlaments. 1943 erfuhr er von der geplanten Deportation der bulgarischen Juden und verhinderte sie mit Unterschriften von Abgeordneten. Er verlor sein Amt und wurde später von den Kommunisten verurteilt. Er starb 1973 mit 78 in Armut.", "Israel ehrte ihn als „Gerechten unter den Völkern“.", "Sein Handeln rettete rund 48 000 Menschen."],
  "Гео Милев": ["Ein bulgarischer Avantgarde-Dichter aus Radnewo. Im Ersten Weltkrieg verwundet, verlor er das rechte Auge. Sein Poem „September“ über den niedergeschlagenen Aufstand von 1923 wurde verboten. 1925 wurde er zur Polizei bestellt und verschwand; er wurde mit 30 ermordet.", "Seine Überreste fand man erst 1954 in einem Massengrab.", "Er studierte in Leipzig und übersetzte europäische Dichter."],
  "Георги Наджаков": ["Ein bulgarischer Physiker aus Dupniza. 1937 entdeckte er den Photoelektret-Effekt, später die Grundlage von Kopierern und Laserdruckern. Er war Professor an der Universität Sofia. Er starb 1981 mit 84.", "Er arbeitete bei Paul Langevin in Paris.", "Ohne seine Entdeckung wären Kopierer vielleicht viel später gekommen."],
  "Иван Странски": ["Ein bulgarischer Physikochemiker aus Sofia, Begründer der Lehre vom Kristallwachstum. Er arbeitete in Sofia und Berlin, wo er Rektor der Technischen Universität war. Er starb 1979 mit 82 in Berlin.", "Das „Stranski-Krastanow-Wachstum“ nutzt man bis heute bei der Chipherstellung."],
  "Иван Милев": ["Ein bulgarischer Maler aus Kasanlak. In kurzer Zeit schuf er märchenhafte Bilder mit Motiven aus Folklore, Legenden und Jugendstil. Er starb 1927 mit 30 an der Spanischen Grippe.", "Sein Bild ist auf dem 5-Lewa-Schein.", "Er malte auch Bühnenbilder."],
  "Христо Смирненски": ["Ein bulgarischer Dichter aus Kukusch. Er schrieb über die Armen und Unterdrückten und auch humorvolle Verse. Er starb 1923 mit 24 an Tuberkulose.", "Sein „Märchen von der Treppe“ liest man in jeder Schule.", "Als Junge verlor er beim Spiel mit Sprengstoff zwei Finger."],
  "Димитър Талев": ["Ein bulgarischer Schriftsteller aus Prilep. Er schrieb den Roman „Der eiserne Leuchter“ und Fortsetzungen über das Leben in Makedonien während der Wiedergeburt. Die Kommunisten schickten ihn in ein Lager. Er starb 1966 mit 68.", "„Der eiserne Leuchter“ zählt zu den beliebtesten bulgarischen Romanen.", "Er war für den Nobelpreis nominiert."],
  "Бертолт Брехт": ["Ein deutscher Dramatiker und Dichter aus Augsburg. Er schrieb die „Dreigroschenoper“ und „Mutter Courage“ und schuf das „epische Theater“, das zum Denken statt nur zum Fühlen bringt. Er floh vor den Nazis und gründete später das Berliner Ensemble. Er starb 1956 mit 58.", "„Die Moritat von Mackie Messer“ aus seiner Oper wurde ein Welthit.", "In Amerika wurde er zu kommunistischen Ansichten verhört und reiste am nächsten Tag ab."],
  "Ерих Мария Ремарк": ["Ein deutscher Schriftsteller aus Osnabrück. Mit 18 im Ersten Weltkrieg verwundet, schrieb er 1929 „Im Westen nichts Neues“, einen der berühmtesten Antikriegsromane. Die Nazis verbrannten seine Bücher, und er emigrierte. Er starb 1970 mit 72 in der Schweiz.", "Seine Schwester wurde von den Nazis hingerichtet, auch seinetwegen.", "Er war mit der Hollywood-Schauspielerin Paulette Goddard verheiratet."],
  "Панчо Владигеров": ["Ein bulgarischer Komponist und Pianist, in Zürich geboren. Er studierte und arbeitete in Berlin, kehrte dann nach Sofia zurück und lehrte an der Musikakademie. Er schrieb die „Bulgarische Rhapsodie Wardar“. Er starb 1978 mit 79.", "Er hatte einen Zwillingsbruder, Ljuben, einen Geiger.", "Die Musikakademie in Sofia trägt seinen Namen."],
  "Ерих Кестнер": ["Ein deutscher Schriftsteller aus Dresden. Er schrieb die Kinderbücher „Emil und die Detektive“, „Das doppelte Lottchen“ und „Das fliegende Klassenzimmer“. Die Nazis verbrannten seine Bücher, und er sah zu. Er starb 1974 mit 75 in München.", "Er war der einzige Autor, der 1933 bei der Verbrennung seiner eigenen Bücher zusah.", "Nach dem „Doppelten Lottchen“ entstand der Film „Ein Zwilling kommt selten allein“."],
  "Илия Бешков": ["Ein bulgarischer Maler und Karikaturist aus Plewen. Mit seinen Karikaturen verspottete er die Macht und den Krieg. Er lehrte an der Kunstakademie. Er starb 1958 mit 57.", "Er schrieb auch Erzählungen und Erinnerungen."],
  "Вернер Хайзенберг": ["Ein deutscher Physiker aus Würzburg, einer der Begründer der Quantenmechanik. Er fand die „Unschärferelation“: Ort und Geschwindigkeit eines Teilchens lassen sich nicht zugleich genau kennen. Mit 31 bekam er den Nobelpreis. Er starb 1976 mit 74.", "Im Krieg leitete er das deutsche Atomprogramm, das keine Bombe hervorbrachte.", "Einen Kern seiner Theorie fand er auf Helgoland, wohin er wegen Heuschnupfen gefahren war."],
  "Ангел Каралийчев": ["Ein bulgarischer Schriftsteller aus Straschiza, Autor von Märchen und Geschichten für Kinder. Er schrieb „Roggenkorn“ und „Das Weizenbrot“. Er starb 1972 mit 69.", "Seine Märchen wurden in Dutzende Sprachen übersetzt.", "Viele seiner Märchen beruhen auf Volksstoffen."],
  "Хайнц Рюман": ["Ein deutscher Schauspieler aus Essen, einer der beliebtesten der deutschen Filmgeschichte. Er spielte in über 100 Filmen, Komödien wie „Die Feuerzangenbowle“ und ernste Rollen. Er starb 1994 mit 92.", "Als begeisterter Pilot flog er bis ins hohe Alter.", "Mit 91 spielte er in einem Film von Wim Wenders."],
  "Джон Атанасов": ["Ein amerikanischer Physiker und Erfinder mit bulgarischem Vater aus Boitschinowzi. 1939–1942 baute er mit Clifford Berry den ersten elektronischen Digitalrechner. Er starb 1995 mit 91.", "Die Idee kam ihm in einer Kneipe am Straßenrand, nach rund 300 km Nachtfahrt.", "1973 entschied ein US-Gericht, dass er den elektronischen Computer erfunden hat."],
  "Златю Бояджиев": ["Ein bulgarischer Maler aus Brezowo. Er malte Dorfszenen, Feste und Straßen in Plowdiw. Nach einem Schlaganfall mit 48 lernte er, mit der linken Hand zu malen, und schuf märchenhafte, figurenreiche Bilder. Er starb 1976 mit 72.", "Seine Bilder nach dem Schlaganfall sind voller winziger Figuren.", "Sein Museum liegt in der Altstadt von Plowdiw."],
  "Филип Кутев": ["Ein bulgarischer Komponist und Dirigent aus Ajtos. Er gründete das Staatliche Ensemble für Volkslieder und -tänze, das die bulgarische Volksmusik weltweit bekannt machte. Er starb 1982 mit 79.", "Sein Ensemble war das erste professionelle Folkloreensemble Bulgariens (1951).", "Seine Frau Maria Kutewa arbeitete mit ihm und führte sein Werk fort."],
  "Макс Шмелинг": ["Ein deutscher Boxer aus Brandenburg, Weltmeister im Schwergewicht. 1936 schlug er den unbesiegten Amerikaner Joe Louis k. o. Später wurde er Geschäftsmann und Louis’ Freund. Er starb 2005 mit 99.", "1938 versteckte er zwei jüdische Jungen in seinem Hotelzimmer und rettete sie.", "Er half, Joe Louis’ Beerdigung zu bezahlen."],
  "Хана Арент": ["Eine deutsch-amerikanische Philosophin aus einer jüdischen Familie in Hannover. Sie floh vor den Nazis nach Frankreich und dann in die USA. Sie schrieb über den Totalitarismus und die „Banalität des Bösen“. Sie starb 1975 mit 69 in New York.", "Im Eichmann-Prozess sah sie kein Monster, sondern einen gewöhnlichen Bürokraten.", "Sie war Schülerin des Philosophen Martin Heidegger."],
  "Емилиян Станев": ["Ein bulgarischer Schriftsteller aus Tarnowo. Er schrieb den Roman „Der Antichrist“, Geschichten über Natur und Tiere und „Der Pfirsichdieb“. Er war leidenschaftlicher Jäger und starb 1979 mit 72.", "„Der Pfirsichdieb“ wurde verfilmt.", "Er streifte gern allein durch die Wälder."],
  "Димитър Димов": ["Ein bulgarischer Schriftsteller und Tierarzt aus Lowetsch. Er schrieb die Romane „Tabak“ und „Verurteilte Seelen“. Als Anatomieprofessor starb er 1966 mit 56 plötzlich in Bukarest.", "„Verurteilte Seelen“ spielt in Spanien während des Bürgerkriegs.", "„Tabak“ musste er auf Druck der Machthaber umschreiben."],
  "Вили Бранд": ["Ein deutscher Politiker aus Lübeck, geboren als Herbert Frahm. Er floh vor den Nazis nach Norwegen, wurde später Regierender Bürgermeister von West-Berlin und Bundeskanzler. Er suchte die Aussöhnung mit Osteuropa und erhielt 1971 den Friedensnobelpreis. Er starb 1992 mit 78.", "1970 kniete er in Warschau vor dem Denkmal für die Opfer des Ghettos, eine Geste, die um die Welt ging.", "Er trat zurück, nachdem sich ein Mitarbeiter als DDR-Spion entpuppt hatte."],
  "Борис Христов": ["Ein bulgarischer Opernbass aus Plowdiw. Er sang auf den größten Bühnen der Welt und war berühmt als Boris Godunow. Er lebte in Italien und starb 1993 mit 79 in Rom. Begraben ist er in Sofia.", "Bevor er Weltstar wurde, sang er im Chor der Alexander-Newski-Kathedrale.", "Er nahm alle Lieder Mussorgskis auf."],
  "Валери Петров": ["Ein bulgarischer Dichter, Dramatiker und Übersetzer aus Sofia. Er schrieb das Drehbuch zu „Ritter ohne Rüstung“ und das „Weiße Märchen“ und übersetzte alle Stücke Shakespeares. Er starb 2014 mit 94.", "Er übersetzte Shakespeares gesamte Dramen allein.", "Lieder mit seinen Texten singt man bis heute."],
  "Блага Димитрова": ["Eine bulgarische Dichterin und Schriftstellerin aus Bjala Slatina. Sie schrieb Gedichte und Romane und wurde nach 1989 Vizepräsidentin Bulgariens. Sie starb 2003 mit 81.", "Im Vietnamkrieg adoptierte sie ein vietnamesisches Mädchen.", "Ihr Roman „Lawine“ wurde verfilmt."],
  "Апостол Карамитев": ["Ein bulgarischer Schauspieler aus Dupniza. Er spielte auf der Bühne und im Film und unterrichtete Generationen von Schauspielern. Er starb 1973 mit 50.", "Sein Sohn Momtschil Karamitew ist ebenfalls Schauspieler."],
  "Георги Калоянчев": ["Ein bulgarischer Schauspieler aus Burgas, „Kalata“, Liebling mehrerer Generationen. Er spielte komische und ernste Rollen auf der Bühne und im Film. Er starb 2012 mit 87.", "Man nannte ihn den „König der Komödie“."],
  "Гюнтер Грас": ["Ein deutscher Schriftsteller aus Danzig. 1959 schrieb er „Die Blechtrommel“ über einen Jungen, der nicht mehr wachsen will. 1999 erhielt er den Nobelpreis, er starb 2015 mit 87.", "Mit 17 war er bei der Waffen-SS, was er erst mit 78 zugab.", "Neben dem Schreiben war er Bildhauer und Grafiker."],
  "Николай Гяуров": ["Ein bulgarischer Opernbass aus Welingrad. Er sang an der Scala, der Met und in Wien und gilt als einer der größten Bässe. Er starb 2004 mit 74 in Modena.", "Er war mit der italienischen Sopranistin Mirella Freni verheiratet."],
  "Михаел Енде": ["Ein deutscher Schriftsteller aus Garmisch. Er schrieb „Momo“, „Die unendliche Geschichte“ und „Jim Knopf und Lukas der Lokomotivführer“. Er starb 1995 mit 65.", "„Die unendliche Geschichte“ ist in zwei Farben gedruckt, eine für jede Welt.", "Den Film zu seinem Buch mochte er nicht und verklagte die Produzenten."],
  "Хелмут Кол": ["Ein deutscher Politiker aus Ludwigshafen. 16 Jahre Kanzler, so lange wie keiner seit Bismarck. 1990 vollendete er die Wiedervereinigung und unterstützte die Einführung des Euro. Er starb 2017 mit 87.", "Man nennt ihn den „Kanzler der Einheit“.", "Ausländische Gäste lud er gern zu Saumagen in seine Pfalz ein."],
  "Христо Явашев – Кристо": ["Ein bulgarischer Künstler aus Gabrowo, weltbekannt als Christo. Mit seiner Frau Jeanne-Claude verhüllte er Gebäude und Landschaften: den Reichstag in Berlin, den Pont Neuf in Paris. Er starb 2020 mit 84 in New York.", "Er und Jeanne-Claude wurden am selben Tag geboren, am 13. Juni 1935.", "Alle Projekte bezahlte er selbst durch den Verkauf von Skizzen."],
  "Невена Коканова": ["Eine bulgarische Schauspielerin aus Dupniza, eine der beliebtesten im Film. Sie spielte etwa in „Die Ikonostase“ und „Der Fürst“. Sie starb 2000 mit 61.", "Sie spielte in über 30 Filmen.", "Sie kam ohne Schauspielausbildung zum Film."],
  "Роми Шнайдер": ["Eine österreichisch-deutsche Schauspielerin aus Wien. Mit 17 wurde sie als Kaiserin Sisi ein Star und drehte später in Frankreich viele starke Filme. Nach dem Tod ihres Sohnes starb sie 1982 mit 43.", "Die Sisi-Rolle hasste sie später, weil alle sie nur damit verbanden.", "Sie war mit Alain Delon verlobt."],
  "Тодор Колев": ["Ein bulgarischer Schauspieler, Showmaster und Sänger aus Schumen. Er spielte in Komödien und moderierte beliebte Fernsehshows. Er starb 2013 mit 74.", "Man nannte ihn „den Großen“.", "Er sang auch eigene Lieder."],
  "Емил Димитров": ["Ein bulgarischer Sänger und Komponist aus Plowdiw, ein Schlagerstar. Er schrieb und sang „Mein Land, mein Bulgarien“. Er starb 2005 mit 64.", "„Mein Land, mein Bulgarien“ ist fast eine zweite Hymne.", "Seine Platten verkauften sich auch in der Sowjetunion millionenfach."],
  "Гена Димитрова": ["Eine bulgarische Sopranistin aus Bejkowo. Sie sang auf den größten Bühnen, der Scala, der Met, der Arena von Verona, und war berühmt als Turandot. Sie starb 2005 mit 64.", "Man nannte sie „die Stimme des Jahrhunderts“.", "Turandot war ihre Paraderolle weltweit."],
  "Стефан Данаилов": ["Ein bulgarischer Schauspieler aus Sofia, ein Publikumsliebling. Er spielte in über 100 Filmen, darunter „Auf jedem Kilometer“, und in italienischen Filmen. Später war er Kulturminister. Er starb 2019 mit 76.", "Die Rolle des Dejanow in „Auf jedem Kilometer“ machte ihn zum Star.", "Er spielte in der italienischen Serie „Allein gegen die Mafia“."],
  "Георги Аспарухов – Гунди": ["Ein bulgarischer Fußballer aus Sofia, Legende von Lewski. Ein eleganter Torjäger, spielte er bei drei Weltmeisterschaften. Er starb 1971 mit 28 bei einem Autounfall.", "Rund 550 000 Menschen kamen zu seiner Beerdigung.", "Er lehnte ein Angebot des AC Mailand ab, um bei Lewski zu bleiben."],
  "Франц Бекенбауер": ["Ein deutscher Fußballer aus München, „der Kaiser“. Kapitän der Nationalmannschaft, Weltmeister als Spieler 1974 und als Teamchef 1990. Er erfand den modernen Libero. Er starb 2024 mit 78.", "Ein WM-Halbfinale spielte er mit ausgekugelter Schulter in der Schlinge.", "Als Junge wollte er zu 1860 München, doch nach einer Ohrfeige eines ihrer Spieler ging er zu Bayern."],
  "Фалко": ["Ein österreichischer Popsänger aus Wien, geboren als Johann Hölzel. Sein „Rock Me Amadeus“ war der erste deutschsprachige Nummer-eins-Hit in den USA. Er starb 1998 mit 40 bei einem Autounfall in der Dominikanischen Republik.", "Schon als Kind hatte er das absolute Gehör.", "„Der Kommissar“ wurde ein Welthit."],
  "Петя Дубарова": ["Eine bulgarische Dichterin aus Burgas. Schon als Schülerin schrieb sie frische, aufrichtige Gedichte und spielte in einem Film. Sie nahm sich 1979 mit 17 das Leben.", "Die meisten ihrer Gedichte erschienen nach ihrem Tod.", "Ihr Haus in Burgas ist ein Museum."],
};
